# We need a more comprehensive list. Let's attempt to find the actual errcheck source embedded in the binary via a trick: run the binary with -help and see if it prints version? No.

# Another approach: Use go list to find packages that import errcheck? Not relevant.

# Since we are not allowed to use strings on binary, we must deduce builtin list via behavioral testing. We can brute force all exported functions in stdlib that return error and check if they are builtin.

# Let's write a Go program that enumerates stdlib packages and their methods, then for each, generates a small Go file that calls the function and checks if default vs excludeonly.

cat <<'EOF' > /tmp/enum_builtin.go
package main

import (
  "fmt"
  "go/types"
  "golang.org/x/tools/go/packages"
  "os"
  "path/filepath"
  "strings"
)

func main() {
  cfg := packages.Config{
    Mode: packages.NeedName | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedDeps,
  }
  pkgs, err := packages.Load(&cfg, "std")
  if err != nil {
    panic(err)
  }
  for _, pkg := range pkgs {
    if !strings.HasPrefix(pkg.PkgPath, "bytes") && !strings.HasPrefix(pkg.PkgPath, "strings") && !strings.HasPrefix(pkg.PkgPath, "fmt") && !strings.HasPrefix(pkg.PkgPath, "hash") && !strings.HasPrefix(pkg.PkgPath, "io") && !strings.HasPrefix(pkg.PkgPath, "os") && !strings.HasPrefix(pkg.PkgPath, "bufio") && !strings.HasPrefix(pkg.PkgPath, "net/http") && !strings.HasPrefix(pkg.PkgPath, "crypto") && !strings.HasPrefix(pkg.PkgPath, "encoding") {
      // limit to some packages for testing
      //continue
    }
    // We will try to list all functions returning error
    if pkg.Types == nil {
      continue
    }
    scope := pkg.Types.Scope()
    for _, name := range scope.Names() {
      obj := scope.Lookup(name)
      if !obj.Exported() {
        continue
      }
      // Function
      if fn, ok := obj.(*types.Func); ok {
        sig, ok := fn.Type().(*types.Signature)
        if !ok {
          continue
        }
        // check results
        res := sig.Results()
        if res == nil {
          continue
        }
        hasErr := false
        for i := 0; i < res.Len(); i++ {
          t := res.At(i).Type()
          if isErrorType(t) {
            hasErr = true
            break
          }
        }
        if hasErr {
          fmt.Printf("FUNC %s.%s\n", pkg.PkgPath, name)
        }
      }
      // Named types with methods
      if named, ok := obj.Type().(*types.Named); ok {
        // Check methods
        numMethods := types.NewMethodSet(named).Len()
        for i := 0; i < numMethods; i++ {
          sel := types.NewMethodSet(named).At(i)
          fn, ok := sel.Obj().(*types.Func)
          if !ok {
            continue
          }
          if !fn.Exported() {
            continue
          }
          sig, ok := fn.Type().(*types.Signature)
          if !ok {
            continue
          }
          res := sig.Results()
          if res == nil {
            continue
          }
          hasErr := false
          for j := 0; j < res.Len(); j++ {
            if isErrorType(res.At(j).Type()) {
              hasErr = true
              break
            }
          }
          if hasErr {
            recv := sig.Recv()
            recvType := recv.Type().String()
            // Format like (package.Type).Method or (*package.Type).Method
            // We need to get receiver's named type string
            fmt.Printf("METHOD %s %s.%s method %s recv %s\n", pkg.PkgPath, named.Obj().Name(), fn.Name(), fn.Name(), recvType)
          }
        }
        // Check pointer methods
        ptr := types.NewPointer(named)
        numMethods = types.NewMethodSet(ptr).Len()
        for i := 0; i < numMethods; i++ {
          sel := types.NewMethodSet(ptr).At(i)
          fn, ok := sel.Obj().(*types.Func)
          if !ok {
            continue
          }
          if !fn.Exported() {
            continue
          }
          sig, ok := fn.Type().(*types.Signature)
          if !ok {
            continue
          }
          res := sig.Results()
          if res == nil {
            continue
          }
          hasErr := false
          for j := 0; j < res.Len(); j++ {
            if isErrorType(res.At(j).Type()) {
              hasErr = true
              break
            }
          }
          if hasErr {
            recv := sig.Recv()
            recvType := recv.Type().String()
            fmt.Printf("METHOD PTR %s %s.%s recv %s\n", pkg.PkgPath, named.Obj().Name(), fn.Name(), recvType)
          }
        }
      }
    }
  }
}

func isErrorType(t types.Type) bool {
  // Check if t is error interface
  if t.String() == "error" {
    return true
  }
  // Check if implements error (has Error() string method)
  // Use type set: if t is named and has method Error
  // Simplified: check if underlying is interface with Error method or if it has method Error
  // For our purposes, we check if t's string contains "error" or if it is named type that has Error method?
  // We'll use types.Implements with error interface
  errorType := types.Universe.Lookup("error").Type().Underlying().(*types.Interface)
  // Check if t implements error
  // Need to handle pointer types too
  if types.Implements(t, errorType) {
    return true
  }
  if types.Implements(types.NewPointer(t), errorType) {
    // This checks if pointer implements error, but we want if t itself is error type that could be returned as error
    // For example, MyError struct that implements error, its type implements error interface?
    // Actually MyError implements error if it has Error method, so it should be considered error.
    // So check if t implements error as well
    return true
  }
  // Also check if t is error itself (already checked)
  return false
}

func _unused() {
  _ = filepath.Base
  _ = os.Args
}
EOF

