func parseExcludeLine(line string) (excludeEntry, error) {
	line = strings.TrimSpace(line)
	base := line
	argFilter := ""
	if strings.HasSuffix(line, ")") {
		lastOpen := strings.LastIndex(line, "(")
		if lastOpen != -1 {
			filterContent := strings.TrimSpace(line[lastOpen+1 : len(line)-1])
			base = strings.TrimSpace(line[:lastOpen])
			argFilter = filterContent
		}
	}
	var entry excludeEntry
	entry.full = line
	entry.argFilter = argFilter
	if argFilter == "os.Stdout" || argFilter == "os.Stderr" {
		entry.argIsSpecial = true
	}
	if strings.HasPrefix(base, "(") {
		closeIdx := strings.Index(base, ")")
		if closeIdx == -1 {
			return entry, fmt.Errorf("invalid")
		}
		receiverInside := strings.TrimSpace(base[1:closeIdx])
		remaining := strings.TrimSpace(base[closeIdx+1:])
		if !strings.HasPrefix(remaining, ".") {
			return entry, fmt.Errorf("invalid")
		}
		methodName := strings.TrimSpace(remaining[1:])
		entry.isMethod = true
		entry.receiver = receiverInside
		entry.funcName = methodName
	} else {
		lastDot := strings.LastIndex(base, ".")
