type excludeEntry struct {
	// For function: pkgPath, funcName
	// For method: receiver, methodName
	// receiver is like "bytes.Buffer" or "*bytes.Buffer" or "example.com/pkg.Type"
	isMethod       bool
	receiver       string // e.g., "bytes.Buffer" or "*bytes.Buffer"
	funcName       string // for function: function name, for method: method name
	pkgPath        string // for function: package path
	full           string // original line
	argFilter      string // e.g., "*bytes.Buffer" or "os.Stdout" or "os.Stderr" or ""
	argIsSpecial   bool   // true if argFilter is os.Stdout or os.Stderr
}

func parseExcludeFile(path string) ([]excludeEntry, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	var entries []excludeEntry
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "//") {
			continue
		}
		// Parse arg filter suffix: look for last '(' that starts suffix at end
		// The suffix is "(...)" at end of line
		base := line
		argFilter := ""
		// Find last '('
		if strings.HasSuffix(line, ")") {
			// Find the matching '(' for the suffix at end
			// We need to find the last '(' that has its corresponding ')' at end
			// Simplistic: find last '(' index
			lastParenOpen := strings.LastIndex(line, "(")
			if lastParenOpen != -1 {
				// Check if what follows is a valid filter and not part of receiver?
				// The base before that '(' should be non-empty and not end with "."?
				// For function like "io.Copy(*bytes.Buffer)", base would be "io.Copy" and filter "*bytes.Buffer"
				// For method like "(bytes.Buffer).Write(*bytes.Buffer)", base would be "(bytes.Buffer).Write" and filter "*bytes.Buffer"
				// How to distinguish receiver's "(" at beginning vs filter's "(" at end?
				// We can attempt: If line starts with "(" then first receiver is at beginning. The filter suffix is the *last* parens at end, which is separate from first.
				// So if line starts with "(", there will be at least two pairs of parens if filter present: first for receiver, last for filter.
				// e.g., "(bytes.Buffer).Write(*bytes.Buffer)" -> first '(' at 0, second '(' at len-15? Actually second '(' is for filter.
				// Our logic: Find last '(' and check if there is a '.' before it in base? For "io.Copy(*bytes.Buffer)", base before last '(' is "io.Copy" which contains '.' but not ").".
				// For "(bytes.Buffer).Write(*bytes.Buffer)", base before last '(' is "(bytes.Buffer).Write" which ends with "Write" and contains ")." .
				// So we can extract filter as content from last '(' to end, stripping outer parens.
				// Then base = line[:lastParenOpen]
				filterContent := strings.TrimSpace(line[lastParenOpen+1 : len(line)-1])
				// filterContent could be "*bytes.Buffer" or "os.Stdout" etc.
				// Check if filterContent contains "." or "*" or "/"? It should be a type or special literal.
				// We will treat it as arg filter if base is not empty and filterContent is not empty.
				// But need to ensure we don't misinterpret receiver's closing paren as filter?
				// For line "(bytes.Buffer).Write", it ends with "Write", not ")", so no suffix.
				// For line "(*bytes.Buffer).Write", ends with "Write", no suffix.
				// So suffix only present if line ends with ")".
				// So we can safely extract last parens as filter if line ends with ")".
				// However for method without filter, line does not end with ")", it ends with method name.
				// For function without filter, line does not end with ")", e.g., "os.ReadFile"
				// So if line ends with ")", it has filter (except when it's method like "(bytes.Buffer).Write" does NOT end with ")", so it's not filter)
				// Wait "(bytes.Buffer).Write" does NOT end with ")", but "(*bytes.Buffer).Write" also does NOT end with ")", ends with "Write".
				// So for method with filter, line DOES end with ")" because filter adds parens at end: "(bytes.Buffer).Write(*bytes.Buffer)" ends with ")".
				// For function with filter, "io.Copy(*bytes.Buffer)" ends with ")".
				// So our detection of suffix at end works: if line ends with ")", extract last "(" as filter start, base = line[:lastParenOpen].
				// But need to handle case where line is "(bytes.Buffer).Write" which does NOT end with ")", so no filter.
				// For "(*bytes.Buffer).Write", does NOT end with ")".
				// Good.

				// Now check if filterContent is valid: it should not contain ")." (since that would be part of base?) Actually filterContent for method receiver would be like "bytes.Buffer" but base for that would be empty? Let's just treat any suffix at end as filter.

				// However we must ensure that for a line like "(*bytes.Buffer).Write", which does NOT end with ")", we don't have filter.
				// For line like "io.Copy(*bytes.Buffer)", we do.

				// So if line ends with ")", we extract filter.

				base = strings.TrimSpace(line[:lastParenOpen])
				argFilter = strings.TrimSpace(filterContent)
			}
		}
		// Now parse base
		// If base starts with "(" then it's method
		var entry excludeEntry
		entry.full = line
		entry.argFilter = argFilter
		if argFilter == "os.Stdout" || argFilter == "os.Stderr" {
			entry.argIsSpecial = true
		}
		if strings.HasPrefix(base, "(") {
			// method
			// Find first closing ")"
			// Need to find matching ")" for first "("
			// Since receiver doesn't have nested parens except for "*", first ")" should close it
			closeIdx := strings.Index(base, ")")
			if closeIdx == -1 {
				// invalid, skip?
				continue
			}
			receiverInside := strings.TrimSpace(base[1:closeIdx])
			// After ")", expect "." and method name
			remaining := strings.TrimSpace(base[closeIdx+1:])
			if !strings.HasPrefix(remaining, ".") {
				// invalid
				continue
			}
			methodName := strings.TrimSpace(remaining[1:])
			// methodName should not contain "(" or ")" or spaces, but could have spaces? Trim.
			// Also methodName may have been left with arg filter? But we already removed filter, so methodName is clean.
			entry.isMethod = true
			entry.receiver = receiverInside // e.g., "bytes.Buffer" or "*bytes.Buffer"
			entry.funcName = methodName
		} else {
			// function
			// Find last dot to separate pkg and func
			lastDot := strings.LastIndex(base, ".")
			if lastDot == -1 {
				// No dot, maybe just function name without package? Treat as func name with empty pkg?
				entry.isMethod = false
				entry.pkgPath = ""
				entry.funcName = base
			} else {
				pkgPath := strings.TrimSpace(base[:lastDot])
				funcName := strings.TrimSpace(base[lastDot+1:])
				entry.isMethod = false
				entry.pkgPath = pkgPath
				entry.funcName = funcName
			}
		}
		entries = append(entries, entry)
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return entries, nil
}

