}

func parseExcludeLine(line string) (excludeEntry, error) {
	line = strings.TrimSpace(line)
	base := line
	argFilter := ""
	if strings.HasSuffix(line, ")") {
		lastOpen := strings.LastIndex(line, "(")
		if lastOpen != -1 {
			filterContent := strings.TrimSpace(line[lastOpen+1 : len(line)-1])
			base = strings.TrimSpace(line[:lastOpen])
			argFilter = filterContent
		}
	}
	var entry excludeEntry
	entry.full = line
	entry.argFilter = argFilter
	if argFilter == "os.Stdout" || argFilter == "os.Stderr" {
		entry.argIsSpecial = true
	}
	if strings.HasPrefix(base, "(") {
		closeIdx := strings.Index(base, ")")
		if closeIdx == -1 {
			return entry, fmt.Errorf("invalid")
		}
		receiverInside := strings.TrimSpace(base[1:closeIdx])
		remaining := strings.TrimSpace(base[closeIdx+1:])
		if !strings.HasPrefix(remaining, ".") {
			return entry, fmt.Errorf("invalid")
		}
		methodName := strings.TrimSpace(remaining[1:])
		entry.isMethod = true
		entry.receiver = receiverInside
		entry.funcName = methodName
	} else {
		lastDot := strings.LastIndex(base, ".")
		if lastDot == -1 {
			entry.isMethod = false
			entry.pkgPath = ""
			entry.funcName = base
		} else {
			entry.isMethod = false
			entry.pkgPath = strings.TrimSpace(base[:lastDot])
			entry.funcName = strings.TrimSpace(base[lastDot+1:])
		}
	}
	return entry, nil
}

// ignore handling
type ignoreRule struct {
	pkgPattern string // may be empty meaning all packages
	re         *regexp.Regexp
	raw        string
}

func parseIgnoreRules(ignores []string) ([]ignoreRule, error) {
	var rules []ignoreRule
	for _, entry := range ignores {
		// entry is like "pkg:regex" or "regex"
		// Split by first colon
		parts := strings.SplitN(entry, ":", 2)
		var pkgPat, reStr string
		if len(parts) == 2 {
			pkgPat = strings.TrimSpace(parts[0])
			reStr = strings.TrimSpace(parts[1])
		} else {
			pkgPat = ""
			reStr = strings.TrimSpace(parts[0])
		}
		if reStr == "" {
			continue
		}
		re, err := regexp.Compile(reStr)
		if err != nil {
			return nil, fmt.Errorf("invalid regex %q: %v", reStr, err)
		}
		rules = append(rules, ignoreRule{pkgPattern: pkgPat, re: re, raw: reStr})
	}
	return rules, nil
}

