cat <<'EOF' > main.go
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
	"go/importer"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

// Flags
var (
	flagAbspath         = flag.Bool("abspath", false, "print absolute paths to files")
	flagAsserts         = flag.Bool("asserts", false, "if true, check for ignored type assertion results")
	flagBlank           = flag.Bool("blank", false, "if true, check for errors assigned to blank identifier")
	flagExclude         = flag.String("exclude", "", "Path to a file containing a list of functions to exclude from checking")
	flagExcludeOnly     = flag.Bool("excludeonly", false, "Use only excludes from -exclude file")
	flagIgnoreGenerated = flag.Bool("ignoregenerated", false, "if true, checking of files with generated code is disabled")
	flagIgnorePkg       = flag.String("ignorepkg", "", "comma-separated list of package paths to ignore")
	flagIgnoreTests     = flag.Bool("ignoretests", false, "if true, checking of _test.go files is disabled")
	flagMod             = flag.String("mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
	flagTags            = flag.String("tags", "", "comma or space-separated list of build tags to include")
	flagVerbose         = flag.Bool("verbose", false, "produce more verbose logging")
)

type ignoreFlag []string

func (i *ignoreFlag) String() string { return strings.Join(*i, ",") }
func (i *ignoreFlag) Set(v string) error {
	for _, part := range strings.Split(v, ",") {
		part = strings.TrimSpace(part)
		if part != "" {
			*i = append(*i, part)
		}
	}
	return nil
}

type tagsFlag []string

func (t *tagsFlag) String() string { return strings.Join(*t, ",") }
func (t *tagsFlag) Set(v string) error {
	parts := strings.FieldsFunc(v, func(r rune) bool {
		return r == ',' || r == ' ' || r == '\t' || r == '\n'
	})
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p != "" {
			*t = append(*t, p)
		}
	}
	return nil
}

var flagIgnore ignoreFlag
var flagTagsList tagsFlag

func init() {
	flag.Var(&flagIgnore, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	flag.Var(&flagTagsList, "tags", "comma or space-separated list of build tags to include")
}

type excludeEntry struct {
	isMethod     bool
	receiver     string // e.g., "bytes.Buffer" or "*bytes.Buffer"
	funcName     string
	pkgPath      string
	full         string
	argFilter    string
	argIsSpecial bool
}

func parseExcludeLine(line string) (excludeEntry, error) {
	line = strings.TrimSpace(line)
	if line == "" {
		return excludeEntry{}, fmt.Errorf("empty")
	}
	base := line
	argFilter := ""
	if strings.HasSuffix(line, ")") {
		lastOpen := strings.LastIndex(line, "(")
		if lastOpen != -1 {
			filterContent := strings.TrimSpace(line[lastOpen+1 : len(line)-1])
			// Ensure base is not empty and filterContent not containing " "?? We treat any suffix as filter if base non-empty
			// However for method like "(*bytes.Buffer).Write", it does NOT end with ")", so not here
			// So this will only trigger for lines that end with ")"
			base = strings.TrimSpace(line[:lastOpen])
			argFilter = filterContent
		}
	}
	var entry excludeEntry
	entry.full = line
	entry.argFilter = argFilter
	if argFilter == "os.Stdout" || argFilter == "os.Stderr" {
		entry.argIsSpecial = true
	}
	if strings.HasPrefix(base, "(") {
		closeIdx := strings.Index(base, ")")
		if closeIdx == -1 {
			return entry, fmt.Errorf("invalid receiver")
		}
		receiverInside := strings.TrimSpace(base[1:closeIdx])
		remaining := strings.TrimSpace(base[closeIdx+1:])
		if !strings.HasPrefix(remaining, ".") {
			return entry, fmt.Errorf("invalid method")
		}
		methodName := strings.TrimSpace(remaining[1:])
		// methodName may contain spaces? Trim.
		// It should not contain "("
		if strings.Contains(methodName, "(") {
			// actually methodName might have been already stripped? But if base had filter, methodName is clean
			// For safety, if methodName contains "(", it's invalid, but we already handled filter
		}
		entry.isMethod = true
		entry.receiver = receiverInside
		entry.funcName = methodName
	} else {
		lastDot := strings.LastIndex(base, ".")
		if lastDot == -1 {
			entry.isMethod = false
			entry.pkgPath = ""
			entry.funcName = base
		} else {
			entry.isMethod = false
			entry.pkgPath = strings.TrimSpace(base[:lastDot])
			entry.funcName = strings.TrimSpace(base[lastDot+1:])
		}
	}
	return entry, nil
}

func parseExcludeFile(path string) ([]excludeEntry, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	var entries []excludeEntry
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "//") {
			continue
		}
		entry, err := parseExcludeLine(line)
		if err != nil {
			// skip invalid lines? Original might skip? Let's skip
			continue
		}
		// Filter out empty funcName
		if entry.funcName == "" {
			continue
		}
		entries = append(entries, entry)
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return entries, nil
}

func builtinExcludes() []excludeEntry {
	lines := []string{
		"(*bytes.Buffer).Write",
		"(*bytes.Buffer).WriteString",
		"(*bytes.Buffer).WriteByte",
		"(*bytes.Buffer).WriteRune",
		"(*strings.Builder).Write",
		"(*strings.Builder).WriteString",
		"(*strings.Builder).WriteByte",
		"(*strings.Builder).WriteRune",
		"(hash.Hash).Write",
		"fmt.Print",
		"fmt.Println",
		"fmt.Printf",
		"fmt.Fprint(*bytes.Buffer)",
		"fmt.Fprintf(*bytes.Buffer)",
		"fmt.Fprintln(*bytes.Buffer)",
		"fmt.Fprint(*strings.Builder)",
		"fmt.Fprintf(*strings.Builder)",
		"fmt.Fprintln(*strings.Builder)",
		"fmt.Fprint(os.Stderr)",
		"fmt.Fprintf(os.Stderr)",
		"fmt.Fprintln(os.Stderr)",
	}
	var entries []excludeEntry
	for _, l := range lines {
		e, err := parseExcludeLine(l)
		if err != nil {
			continue
		}
		entries = append(entries, e)
	}
	return entries
}

type ignoreRule struct {
	pkgPattern string
	re         *regexp.Regexp
}

func parseIgnoreRules(ignores []string) ([]ignoreRule, error) {
	var rules []ignoreRule
	for _, entry := range ignores {
		parts := strings.SplitN(entry, ":", 2)
		var pkgPat, reStr string
		if len(parts) == 2 {
			pkgPat = strings.TrimSpace(parts[0])
			reStr = strings.TrimSpace(parts[1])
		} else {
			pkgPat = ""
			reStr = strings.TrimSpace(parts[0])
		}
		if reStr == "" {
			continue
		}
		re, err := regexp.Compile(reStr)
		if err != nil {
			return nil, fmt.Errorf("invalid regex %q: %v", reStr, err)
		}
		rules = append(rules, ignoreRule{pkgPattern: pkgPat, re: re})
	}
	return rules, nil
}

// go list
type goListPkg struct {
	Dir               string   `json:"Dir"`
	ImportPath        string   `json:"ImportPath"`
	Name              string   `json:"Name"`
	GoFiles           []string `json:"GoFiles"`
	CompiledGoFiles   []string `json:"CompiledGoFiles"`
	TestGoFiles       []string `json:"TestGoFiles"`
	XTestGoFiles      []string `json:"XTestGoFiles"`
	IgnoredGoFiles    []string `json:"IgnoredGoFiles"`
	ForTest           string   `json:"ForTest"`
	Deps              []string `json:"Deps"`
	Error             *struct {
		Err string `json:"Err"`
	} `json:"Error"`
}

func loadPackages(patterns []string, tags []string, mod string) ([]goListPkg, error) {
	args := []string{"list", "-json"}
	if len(tags) > 0 {
		args = append(args, "-tags", strings.Join(tags, ","))
	}
	if mod != "" {
		args = append(args, "-mod", mod)
	}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	var out bytes.Buffer
	var errOut bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errOut
	err := cmd.Run()
	// Even if error, we try to parse output
	if out.Len() == 0 && err != nil {
		// No output, return error
		return nil, fmt.Errorf("go list failed: %v stderr: %s", err, errOut.String())
	}
	dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
	var pkgs []goListPkg
	for {
		var p goListPkg
		if err := dec.Decode(&p); err != nil {
			if err == io.EOF {
				break
			}
			break
		}
		pkgs = append(pkgs, p)
	}
	// Check for errors in packages
	var loadErrors []string
	for _, p := range pkgs {
		if p.Error != nil {
			loadErrors = append(loadErrors, fmt.Sprintf("%s: %s", p.ImportPath, p.Error.Err))
		}
	}
	if len(loadErrors) > 0 && err != nil {
		// Return error with list
		// Format similar to original: "errors while loading package <pattern>: [...]"
		// We'll construct error string
		return pkgs, fmt.Errorf("load errors: %v stderr: %s", loadErrors, errOut.String())
	}
	if err != nil && errOut.Len() > 0 {
		// If go list stderr contains errors about package not found, we should return error
		// The original binary prints "error: failed to check packages: errors while loading package <pattern>: [-: package <pattern> is not in std ...]"
		// We will handle at higher level
		return pkgs, fmt.Errorf("%s", errOut.String())
	}
	return pkgs, nil
}

// Helper to check if type is error
func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	// Check if type string is "error"
	if t.String() == "error" {
		return true
	}
	// Check if implements error interface
	// Get error interface type
	errType := types.Universe.Lookup("error").Type()
	if errType != nil {
		// Check if t implements error
		// Use identical or implements
		// For named types that implement error, we need to check method set
		// We can use types.Implements
		// Need to get error interface underlying
		if iface, ok := errType.Underlying().(*types.Interface); ok {
			if types.Implements(t, iface) {
				return true
			}
			// Also check pointer to t
			if types.Implements(types.NewPointer(t), iface) {
				// Actually if t is struct that has Error method on pointer receiver, then pointer implements error, but value may not
				// But for return types, if function returns MyError (struct) that implements error via pointer receiver, it still is considered error? In Go, if MyError implements error via value receiver, then both value and pointer implement. If via pointer receiver only, then only *MyError implements error, not MyError. So returning MyError (value) where only *MyError implements error would not be error type. So checking pointer implements is not sufficient for value.
				// However we also need to consider that if t is MyError and *MyError implements error, then MyError may not implement, but returning MyError that doesn't implement error is not error. So we should not treat pointer implements as error for value type.
				// But for simplicity, we check if t itself implements error
			}
		}
	}
	return false
}

func isErrorTuple(t types.Type) ([]int, bool) {
	// Returns indices of results that are error type, and whether any error
	if tup, ok := t.(*types.Tuple); ok {
		var idxs []int
		for i := 0; i < tup.Len(); i++ {
			if isErrorType(tup.At(i).Type()) {
				idxs = append(idxs, i)
			}
		}
		return idxs, len(idxs) > 0
	}
	if isErrorType(t) {
		return []int{0}, true
	}
	return nil, false
}

// Check if file is generated
func isGeneratedFile(path string) bool {
	// Read file, check for "Code generated" and "DO NOT EDIT"
	data, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	s := string(data)
	// Simple heuristic: contains "Code generated" and "DO NOT EDIT"
	if strings.Contains(s, "Code generated") && strings.Contains(s, "DO NOT EDIT") {
		return true
	}
	return false
}

// For matching exclude entries
func matchExclude(entry excludeEntry, pkgPath, funcName, receiver string, firstArgType string, firstArgIsStdout, firstArgIsStderr bool) bool {
	// Check arg filter first
	if entry.argFilter != "" {
		if entry.argIsSpecial {
			if entry.argFilter == "os.Stdout" {
				if !firstArgIsStdout {
					return false
				}
			} else if entry.argFilter == "os.Stderr" {
				if !firstArgIsStderr {
					return false
				}
			}
		} else {
			// Type filter: compare firstArgType string
			// firstArgType is like "*bytes.Buffer" or "bytes.Buffer" etc.
			if firstArgType == "" {
				return false
			}
			// For matching, we compare exact string? Original might do exact match
			if firstArgType != entry.argFilter {
				return false
			}
		}
	}
	if entry.isMethod {
		// Compare receiver and funcName
		if entry.funcName != funcName {
			return false
		}
		// Receiver comparison: exact match
		// entry.receiver is like "bytes.Buffer" or "*bytes.Buffer"
		// receiver param is like "bytes.Buffer" or "*bytes.Buffer" or "example.com/pkg.Type"
		if entry.receiver != receiver {
			return false
		}
		return true
	} else {
		// Function
		if entry.funcName != funcName {
			return false
		}
		// If entry.pkgPath is empty, matches any package? Probably yes for function without package?
		// If entry.pkgPath non-empty, need to match pkgPath
		// For function, pkgPath is import path
		// For matching, if entry.pkgPath contains "/" then it must match exactly? Or suffix? Original handles vendoring: full import path including vendor
		// We'll do exact match, but also allow matching if pkgPath is suffix? For simplicity, exact match.
		// Also, if entry.pkgPath is like "fmt", it should match "fmt" package.
		if entry.pkgPath != "" {
			// For function, pkgPath from exclude file is like "io", "fmt", "example.com/pkg"
			// We should match if pkgPath == entry.pkgPath or if entry.pkgPath is suffix? Let's do exact or suffix after vendor?
			// The README mentions vendored dependencies: specify full import path including vendor. So matching should be exact.
			if pkgPath != entry.pkgPath {
				// Also check if pkgPath ends with entry.pkgPath? For vendoring, original might still match exact, but we can also check suffix?
				// Let's do exact match for now
				return false
			}
		}
		return true
	}
}

func getFirstArgInfo(call *ast.CallExpr, info *types.Info) (argType string, isStdout bool, isStderr bool) {
	if len(call.Args) == 0 {
		return "", false, false
	}
	firstArg := call.Args[0]
	// Check if it's selector os.Stdout or os.Stderr
	if sel, ok := firstArg.(*ast.SelectorExpr); ok {
		if ident, ok := sel.X.(*ast.Ident); ok {
			if ident.Name == "os" {
				if sel.Sel.Name == "Stdout" {
					return "os.Stdout", true, false
				}
				if sel.Sel.Name == "Stderr" {
					return "", false, true
				}
			}
		}
	}
	// Get type of first arg
	t := info.TypeOf(firstArg)
	if t != nil {
		// Format type string similar to exclude file: e.g., "*bytes.Buffer"
		// Use types.TypeString with qualifier that returns package path? We need to get string like "*bytes.Buffer"
		// For qualified, we can use types.TypeString with a qualifier that returns package name? Let's use nil qualifier which gives fully qualified? Actually with nil, it gives package-qualified string like "bytes.Buffer" for named types in other packages, and for pointer "*bytes.Buffer"
		// Let's try
		argType = types.TypeString(t, func(p *types.Package) string {
			if p == nil {
				return ""
			}
			// Return package path? Or name?
			// For matching "*bytes.Buffer", we want "bytes.Buffer" not full path? Original exclude examples use "bytes.Buffer" not "github.com/.../bytes.Buffer" for stdlib, but for custom packages they use full path? The README example: "io.Copy(*bytes.Buffer)" uses "bytes.Buffer" not full path for stdlib.
			// For custom packages, they might use full path? The example for vendoring uses full path.
			// So we need to return package name? Or path? Let's use p.Name() for stdlib? Actually for bytes, p.Name() is "bytes" and p.Path() is "bytes" (same). For custom, p.Path() is full path, p.Name() is last element.
			// The exclude file for custom with full path uses full path, not just name. So we should return Path()?
			// Let's return Path() if it contains "/" or "."? Actually for stdlib, Path() == Name(), so both give same.
			// For custom, Path() is full path, Name() is short. The exclude file with full path would need Path().
			// So return Path()
			return p.Path()
		})
		// argType now is like "*bytes.Buffer" or "bytes.Buffer" or "*os.File" etc.
		// For os.Stdout case, type is "*os.File", but we have special handling, so we already returned special.
		// For our matching, we need type string like "*bytes.Buffer" which should match filter "*bytes.Buffer"
	}
	return argType, false, false
}

func getFuncInfo(call *ast.CallExpr, info *types.Info) (pkgPath string, funcName string, receiver string, isMethod bool) {
	// Try to get the called object's type
	// For selector like os.Chdir, Fun is SelectorExpr
	// For ident like foo(), Fun is Ident
	// We need to get the object via Uses
	switch fun := call.Fun.(type) {
	case *ast.SelectorExpr:
		// Could be pkg.Func or receiver.Method
		// Check if object is function
		if obj, ok := info.Uses[fun.Sel]; ok {
			if fn, ok := obj.(*types.Func); ok {
				sig, ok := fn.Type().(*types.Signature)
				if ok {
					// Check if method
					if recv := sig.Recv(); recv != nil {
						// Method
						isMethod = true
						funcName = fn.Name()
						recvType := recv.Type()
						// Format receiver string
						// For pointer receiver, recvType is *Named, string like "*bytes.Buffer"
						// We need to get string like "bytes.Buffer" or "*bytes.Buffer" with package path
						receiver = types.TypeString(recvType, func(p *types.Package) string {
							if p == nil {
								return ""
							}
							return p.Path()
						})
						// receiver now is like "*bytes.Buffer" or "bytes.Buffer" or "*example.com/pkg.Type"
						// Need to strip any leading? It should already be like "*bytes.Buffer"
						// For method, the receiver in exclude is like "bytes.Buffer" or "*bytes.Buffer" without parens, but with star inside if pointer
						// Our receiver string is already like "*bytes.Buffer" or "bytes.Buffer"
						// For verbose identifier, we need to format as "(*receiver).Method" if pointer, else "(receiver).Method"
						// But for matching, we use receiver string without parens
						// pkgPath for method is not used, but we have receiver
						return "", funcName, receiver, true
					} else {
						// Function
						isMethod = false
						funcName = fn.Name()
						if fn.Pkg() != nil {
							pkgPath = fn.Pkg().Path()
						} else {
							// Check if selector's X is package name?
							// For os.Chdir, X is Ident "os" which is package name, its object is package?
							// We can get package from fun.X
							if ident, ok := fun.X.(*ast.Ident); ok {
								if pkgNameObj, ok := info.Uses[ident]; ok {
									if pkgName, ok := pkgNameObj.(*types.PkgName); ok {
										pkgPath = pkgName.Imported().Path()
									}
								}
							}
						}
						return pkgPath, funcName, "", false
					}
				}
			}
		}
		// If not found via Uses, try type of X?
		// For method call like b.Write, fun.X is b (variable), fun.Sel is Write
		// info.Uses[fun.Sel] should give method object, we handled
		// For package func like a.Foo() where a is package name, X is package name ident, Sel is Foo
		// info.Uses[Sel] should give function
	case *ast.Ident:
		// Local function
		if obj, ok := info.Uses[fun]; ok {
			if fn, ok := obj.(*types.Func); ok {
				sig, ok := fn.Type().(*types.Signature)
				if ok {
					if recv := sig.Recv(); recv != nil {
						isMethod = true
						funcName = fn.Name()
						recvType := recv.Type()
						receiver = types.TypeString(recvType, func(p *types.Package) string {
							if p == nil {
								return ""
							}
							return p.Path()
						})
						return "", funcName, receiver, true
					} else {
						isMethod = false
						funcName = fn.Name()
						if fn.Pkg() != nil {
							// If same package, Pkg().Path() is import path of current package
							// For local function, we might want pkgPath to be current package's import path?
							pkgPath = fn.Pkg().Path()
						}
						return pkgPath, funcName, "", false
					}
				}
			}
		}
	}
	return "", "", "", false
}

func main() {
	flag.Parse()
	patterns := flag.Args()
	if len(patterns) == 0 {
		patterns = []string{"."}
	}

	// Load excludes
	var excludeEntries []excludeEntry
	if *flagExclude != "" {
		entries, err := parseExcludeFile(*flagExclude)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
			os.Exit(2)
		}
		excludeEntries = append(excludeEntries, entries...)
	}
	if !*flagExcludeOnly {
		excludeEntries = append(excludeEntries, builtinExcludes()...)
	}

	ignoreRules, err := parseIgnoreRules(flagIgnore)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}
	var ignorePkgs []string
	if *flagIgnorePkg != "" {
		for _, p := range strings.Split(*flagIgnorePkg, ",") {
			p = strings.TrimSpace(p)
			if p != "" {
				ignorePkgs = append(ignorePkgs, p)
			}
		}
	}

	// Load packages via go list
	// Build args for go list
	goListArgs := []string{"list", "-json"}
	if len(flagTagsList) > 0 {
		goListArgs = append(goListArgs, "-tags", strings.Join(flagTagsList, ","))
	}
	if *flagMod != "" {
		goListArgs = append(goListArgs, "-mod", *flagMod)
	}
	goListArgs = append(goListArgs, patterns...)
	cmd := exec.Command("go", goListArgs...)
	var outBuf bytes.Buffer
	var errBuf bytes.Buffer
	cmd.Stdout = &outBuf
	cmd.Stderr = &errBuf
	if err := cmd.Run(); err != nil {
		// Even if error, try to parse output, but if no output, treat as failure
		if outBuf.Len() == 0 {
			// Print error similar to original
			// Original format: "error: failed to check packages: errors while loading package <pattern>: [-: <err>]"
			// We'll use first pattern for message
			msg := strings.TrimSpace(errBuf.String())
			if msg == "" {
				msg = err.Error()
			}
			// Need to format as per original: it lists patterns that failed?
			// For simplicity, print for each pattern that failed?
			// Original prints for each pattern that is not in std or not found
			// We'll print generic
			fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s: [-: %s]\n", patterns[0], msg)
			os.Exit(2)
		}
	}

	dec := json.NewDecoder(bytes.NewReader(outBuf.Bytes()))
	var pkgs []goListPkg
	for {
		var p goListPkg
		if err := dec.Decode(&p); err != nil {
			if err == io.EOF {
				break
			}
			break
		}
		pkgs = append(pkgs, p)
	}

	// Check for package errors
	var loadErrs []string
	for _, p := range pkgs {
		if p.Error != nil {
			loadErrs = append(loadErrs, fmt.Sprintf("%s: %s", p.ImportPath, p.Error.Err))
		}
	}
	if len(loadErrs) > 0 {
		// Print error and exit 2
		// Original prints: "error: failed to check packages: errors while loading package <pattern>: [list]"
		// We'll print first error
		fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s: [%s]\n", patterns[0], strings.Join(loadErrs, " "))
		os.Exit(2)
	}

	// For each package, check if ignored via ignorepkg
	var packagesToCheck []goListPkg
	for _, pkg := range pkgs {
		// Check ignorepkg
		ignored := false
		for _, ip := range ignorePkgs {
			if pkg.ImportPath == ip {
				ignored = true
				break
			}
		}
		if ignored {
			continue
		}
		// Also check ignore rules for pkg: if ignorepkg list via ignore rules? Actually ignorepkg is separate, but ignore rules with regex ".*" for pkg would also ignore
		// For simplicity, if any ignore rule has pkgPattern == pkg.ImportPath and regex matches ".*", then ignore? We'll handle later per function
		packagesToCheck = append(packagesToCheck, pkg)
	}

	// Now for each package, parse and type-check files
	type fileResult struct {
		filename string
		absPath  string
		issues   []issue
	}

	type issue struct {
		pos       token.Position
		callText  string // e.g., "foo()" or "os.Chdir(\"/tmp\")"
		identifier string // e.g., "os.Chdir" or "(*bytes.Buffer).Write" or "example.com/pkg.Foo"
	}

	var allIssues []fileResult
	cwd, _ := os.Getwd()

	for _, pkg := range packagesToCheck {
		if *flagVerbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", pkg.ImportPath)
		}
		fset := token.NewFileSet()
		var astFiles []*ast.File
		var filePaths []string
		// Combine GoFiles and CompiledGoFiles? For simplicity, use GoFiles
		files := pkg.GoFiles
		// Handle ignoretests
		if *flagIgnoreTests {
			var filtered []string
			for _, f := range files {
				if strings.HasSuffix(f, "_test.go") {
					continue
				}
				filtered = append(filtered, f)
			}
			files = filtered
		}
		// For each file, check if generated and ignore if needed
		var validFiles []string
		for _, fname := range files {
			fpath := filepath.Join(pkg.Dir, fname)
			if *flagIgnoreGenerated {
				if isGeneratedFile(fpath) {
					continue
				}
			}
			validFiles = append(validFiles, fname)
		}
		files = validFiles
		if len(files) == 0 {
			continue
		}
		for _, fname := range files {
			fpath := filepath.Join(pkg.Dir, fname)
			src, err := os.ReadFile(fpath)
			if err != nil {
				continue
			}
			file, err := parser.ParseFile(fset, fpath, src, parser.AllErrors|parser.ParseComments)
			if err != nil {
				// Type errors will be caught later, but parse errors should cause load failure?
				// For simplicity, continue
			}
			if file != nil {
				astFiles = append(astFiles, file)
				filePaths = append(filePaths, fpath)
			}
		}
		if len(astFiles) == 0 {
			continue
		}
		// Type check
		conf := types.Config{
			Importer: importer.ForCompiler(token.NewFileSet(), "gc", nil),
		}
		info := &types.Info{
			Types: make(map[ast.Expr]types.TypeAndValue),
			Defs:  make(map[*ast.Ident]types.Object),
			Uses:  make(map[*ast.Ident]types.Object),
		}
		_, err := conf.Check(pkg.ImportPath, fset, astFiles, info)
		if err != nil {
			// If type check error, treat as load failure and exit 2
			// Original message: "error: failed to check packages: errors while loading package <importPath>: [-: # <importPath>\n<file>:...]"
			// We'll print similar
			fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s: [-: # %s\n%s]\n", pkg.ImportPath, pkg.ImportPath, err.Error())
			os.Exit(2)
		}

		// Now inspect each file for unchecked errors
		for idx, file := range astFiles {
			fpath := filePaths[idx]
