		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}

	var ignorePkgs []string
	if *flagIgnorePkg != "" {
		for _, p := range strings.Split(*flagIgnorePkg, ",") {
			p = strings.TrimSpace(p)
			if p != "" {
				ignorePkgs = append(ignorePkgs, p)
			}
		}
	}

	pkgs, err := loadGoList(patterns, flagTags, *flagMod)
	if err != nil {
		// Format like original: "error: failed to check packages: ..."
		// The error message from loadGoList already contains "errors while loading package ..."
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}

	// For verbose, print checking to stderr
	cwd, _ := os.Getwd()

	hasErrors := false

	for _, pkg := range pkgs {
		// Check if pkg should be ignored via ignorepkg
		ignoredPkg := false
		for _, ip := range ignorePkgs {
			if pkg.ImportPath == ip {
				ignoredPkg = true
				break
			}
		}
		if ignoredPkg {
			continue
		}
		// Also check ignore rules that apply to all funcs in pkg? Actually ignorepkg takes precedence, but ignore rules with pkg:.* also ignore
		// We'll check later for each call, but we can also skip pkg if any ignore rule matches pkg with ".*"?
		// For simplicity, skip if pkg matches ignorepkg list via exact match or via ignore rule that is "pkg:.*"
		// We'll handle per-call.

		if *flagVerbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", pkg.ImportPath)
		}

		fset := token.NewFileSet()
		var files []*ast.File
		var filePaths []string // full path
		var fileContents [][]byte

		// Determine which GoFiles to use
		goFiles := pkg.GoFiles
		// If ignoretests, we already excluded test files because go list without -test doesn't include them, but need to handle TestGoFiles etc?
		// go list with default does not include test files in GoFiles, only in TestGoFiles. So we are good for ignoretests.
		// However if user wants to include tests, they need to include test files? How does original handle? It checks _test.go files by default, unless -ignoretests. So we need to include TestGoFiles when ignoretests is false.
		// Let's include TestGoFiles if not ignoretests
		if !*flagIgnoreTests {
			// GoFiles already excludes test files? Actually go list's GoFiles excludes test files, TestGoFiles contains them.
			// So to include tests, we need to add TestGoFiles and XTestGoFiles
			// Let's add them
			// But our pkgInfo currently only has GoFiles, not TestGoFiles. We need to parse TestGoFiles as well.
			// For now, we need to re-parse go list with more fields
		}

		for _, fname := range goFiles {
			fpath := filepath.Join(pkg.Dir, fname)
			src, err := os.ReadFile(fpath)
			if err != nil {
				continue
			}
			// Check ignoregenerated
			if *flagIgnoreGenerated {
				if isGeneratedFile(src) {
					continue
				}
			}
			// Check ignoretests - file name ends with _test.go
			if *flagIgnoreTests && strings.HasSuffix(fname, "_test.go") {
				continue
			}
			f, err := parser.ParseFile(fset, fpath, src, parser.AllErrors|parser.ParseComments)
			if err != nil {
				// If parse error, treat as load error? Original would have failed earlier during go list? But if file has syntax error, it would be type check error, not load error.
				// Continue
				continue
			}
			files = append(files, f)
			filePaths = append(filePaths, fpath)
			fileContents = append(fileContents, src)
		}

		if len(files) == 0 {
			continue
		}

		conf := types.Config{
			Importer: importer.ForCompiler(fset, "gc", nil),
		}
		info := &types.Info{
			Types: make(map[ast.Expr]types.TypeAndValue),
			Defs:  make(map[*ast.Ident]types.Object),
			Uses:  make(map[*ast.Ident]types.Object),
		}
		_, err = conf.Check(pkg.ImportPath, fset, files, info)
		if err != nil {
			// Type check errors are considered load errors? Original returns exit 2 with error message
			// The error message includes "# package" and file:line:col: message
			// Example: "error: failed to check packages: errors while loading package example.com/testpkg: [-: # example.com/testpkg\n./main2.go:11:9: assignment mismatch: ...]"
			// So we need to format error as "errors while loading package <importPath>: [<error>]"
			// The error from types.Check is like ".../main.go:11:9: ..."
			// For simplicity, we will output similar format: "error: failed to check packages: errors while loading package <importPath>: [-: <err>]"
			// But need to include file path relative? The original includes both relative and absolute? It shows "./main2.go:..." and "/tmp/.../main2.go:..."
			// Let's print error as is and exit 2
			fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s: [-: %v]\n", pkg.ImportPath, err)
			os.Exit(2)
		}

		// Walk each file
		for fileIdx, file := range files {
			fpath := filePaths[fileIdx]
			src := fileContents[fileIdx]
			// Map file to its ast file for position
			var stack []ast.Node
			ast.Inspect(file, func(n ast.Node) bool {
				if n == nil {
					if len(stack) > 0 {
						stack = stack[:len(stack)-1]
					}
					return true
				}
				stack = append(stack, n)

				// Handle CallExpr
				call, ok := n.(*ast.CallExpr)
				if ok {
					// Check if it returns error
					t := info.TypeOf(call)
					if t == nil {
						return true
					}
					var errPositions []int
					if tup, ok := t.(*types.Tuple); ok {
						for i:=0;i<tup.Len();i++{
							if isErrorType(tup.At(i).Type()){
								errPositions = append(errPositions, i)
							}
						}
					} else {
						if isErrorType(t) {
							errPositions = append(errPositions, 0)
						}
					}
					if len(errPositions)==0 {
						return true
					}

					// Determine if unchecked
					unchecked, blankPos := isUncheckedCall(call, stack, errPositions, *flagBlank)

					if !unchecked {
						return true
					}

					// Build callInfo for exclude matching
					ci := buildCallInfo(call, info, fset, file, fpath, src, pkg, errPositions)

					// Check excludes
					if isExcluded(ci, excludeEntries) {
						return true
					}
					// Check ignorepkg
					if isIgnoredByIgnorePkg(pkg.ImportPath, ignorePkgs) {
						return true
					}
					// Check ignore rules
					if isIgnoredByRules(ci, ignoreRules, pkg.ImportPath) {
						return true
					}

					// Report
					hasErrors = true
					// Determine filename to print
					printFile := fpath
					if !*flagAbspath {
						// Make relative to cwd if possible
						rel, err := filepath.Rel(cwd, fpath)
						if err == nil {
							printFile = rel
						} else {
							// Use base or original?
							printFile = fpath
						}
					}
					pos := fset.Position(call.Pos())
					// pos.Filename is fpath, but we want printFile
					// line:col
					// callText
					callText := extractCallText(src, fset, call)
					if *flagVerbose {
						// identifier + "\t" + callText, except for same-package funcs where identifier omitted? We need to implement logic
						identifier := ci.identifier
						// For same-package funcs (non-method), omit identifier in verbose? Let's check: if identifier is same as func name without args and package is same, we should omit?
						// According to observed: for local funcs in same package, verbose output is same as non-verbose (only callText)
						// So we will implement: if !isMethod and ci.pkgPath == pkg.ImportPath (same package), then don't print identifier, only callText
						// For methods, always print identifier
						if !ci.isMethod && ci.pkgPath == pkg.ImportPath {
							// same package func, print only callText
							fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, callText)
						} else {
							// If identifier empty? Then just callText
							if identifier == "" {
								fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, callText)
							} else {
								fmt.Printf("%s:%d:%d:\t%s\t%s\n", printFile, pos.Line, pos.Column, identifier, callText)
							}
						}
					} else {
						fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, callText)
					}
					_ = blankPos
				}

				// Handle TypeAssertExpr if asserts enabled
				if *flagAsserts {
					if ta, ok := n.(*ast.TypeAssertExpr); ok {
						// Type assertion returns the asserted type, not error, but we treat as needing check
						// Determine if unchecked similar to call
						// For type assertion, the result is the asserted type, but we consider it as error-like for checking
						// The type assertion expression's parent determines if checked
						// For comma-ok form, the assignment will have 2 LHS, second is bool, first is asserted type
						// We need to check if the asserted value is ignored or assigned to blank

						// For simplicity, treat any TypeAssertExpr as returning "error-like" result at position 0
						// And check if parent is ExprStmt -> unchecked, etc.

						// Determine parent
						if len(stack) >=2 {
							parent := stack[len(stack)-2]
							unchecked := false
							isBlank := false
							switch p := parent.(type) {
							case *ast.ExprStmt:
								unchecked = true
							case *ast.DeferStmt, *ast.GoStmt:
								unchecked = true
							case *ast.AssignStmt:
								// If RHS is this type assert, check LHS
								for rhsIdx, rhs := range p.Rhs {
									if rhs == ta {
										// For type assert, if it's comma-ok, the LHS has 2 elements, first is value, second is bool
										// If LHS has 1 element, it's single-value assert
										// If LHS[0] is blank, then blank assign
										if len(p.Lhs) == 1 {
											if ident, ok := p.Lhs[0].(*ast.Ident); ok && ident.Name == "_" {
												isBlank = true
												if *flagBlank {
													unchecked = true
												}
											} else {
												// assigned to non-blank, checked
											}
										} else if len(p.Lhs) == 2 {
											// x, ok := y.(T) -> first is value, second is ok
											// If first is blank, it's blank assign of asserted value
											if ident, ok := p.Lhs[0].(*ast.Ident); ok && ident.Name == "_" {
												isBlank = true
												if *flagBlank {
													unchecked = true
												}
											}
											// If second is blank? That's ok bool, not asserted value, so ignore? But blank for ok might still be considered? For simplicity, only check first.
										}
									} else {
										// If RHS has multiple and this is one of them, check corresponding LHS
										if rhsIdx < len(p.Lhs) {
											if ident, ok := p.Lhs[rhsIdx].(*ast.Ident); ok && ident.Name == "_" {
												isBlank = true
												if *flagBlank {
													unchecked = true
												}
											}
										}
									}
								}
							default:
								// used elsewhere, checked
							}
							if unchecked {
								// Build call info for type assert? For exclude matching, type asserts might also be excluded? The -asserts flag enables checking, but excludes might still apply? Probably yes, but we will treat similarly.
								// For now, we will report
								hasErrors = true
								printFile := fpath
								if !*flagAbspath {
									rel, err := filepath.Rel(cwd, fpath)
									if err == nil {
										printFile = rel
									}
								}
								pos := fset.Position(ta.Pos())
								callText := extractTypeAssertText(src, fset, ta)
								// For verbose, identifier? For type assert, what does original show? Let's test.
								// For foo().(int), verbose showed "foo().(int)" as call? Actually earlier we saw for type assert, verbose would show something?
								// We haven't tested verbose for type assert. Let's assume similar: identifier is type assert result type? Or just call?
								// For simplicity, print callText only, but with verbose, maybe print identifier as type?
								// We will need to test.

								if *flagVerbose {
									// For type assert, what is identifier? Possibly the asserted type? Let's for now just print callText
									fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, callText)
								} else {
									fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, callText)
								}
								_ = isBlank
							}
						}
					}
				}

				return true
			})
		}
	}

	if hasErrors {
		os.Exit(1)
	}
	os.Exit(0)
}

func parseExcludeFileOrBuiltin() ([]excludeEntry, error) {
	var entries []excludeEntry
	if *flagExclude != "" {
		fileEntries, err := parseExcludeFile(*flagExclude)
		if err != nil {
			return nil, err
		}
		entries = append(entries, fileEntries...)
	}
	if !*flagExcludeOnly {
		entries = append(entries, builtinExcludes()...)
	}
	return entries, nil
}

func isGeneratedFile(src []byte) bool {
	// Check if contains "Code generated" and "DO NOT EDIT"
	s := string(src)
	return strings.Contains(s, "Code generated") && strings.Contains(s, "DO NOT EDIT")
}

func isUncheckedCall(call *ast.CallExpr, stack []ast.Node, errPositions []int, blankFlag bool) (bool, int) {
	if len(stack) < 2 {
		return false, -1
	}
	parent := stack[len(stack)-2]
	switch p := parent.(type) {
	case *ast.ExprStmt:
		return true, -1
	case *ast.DeferStmt:
		return true, -1
	case *ast.GoStmt:
		return true, -1
	case *ast.AssignStmt:
		// If RHS has single expr that is this call
		if len(p.Rhs) == 1 {
			// This call returns multiple values, LHS should have same len as results
			// For each errPos, check LHS[errPos] if blank
			for _, ep := range errPositions {
				if ep < len(p.Lhs) {
					lhs := p.Lhs[ep]
					if ident, ok := lhs.(*ast.Ident); ok {
						if ident.Name == "_" {
							if blankFlag {
								return true, ep
							} else {
								// blank allowed, so not unchecked
								continue
							}
						}
					} else {
						// LHS is not ident (e.g., selector, index), considered checked
						continue
					}
				} else {
					// LHS too short, then error not assigned? That would be unchecked? But should be compile error, ignore
				}
			}
			// If we reach here, no blank error positions that are flagged, so checked
			return false, -1
		} else {
			// Multiple RHS, find index of this call
			for rhsIdx, rhs := range p.Rhs {
				if rhs == call {
					if rhsIdx < len(p.Lhs) {
						lhs := p.Lhs[rhsIdx]
						if ident, ok := lhs.(*ast.Ident); ok {
							if ident.Name == "_" {
								if blankFlag {
									return true, rhsIdx
								} else {
									return false, -1
								}
							} else {
								return false, -1
							}
						} else {
							return false, -1
						}
					}
				}
			}
			return false, -1
		}
	default:
		// In other contexts (return, arg, etc) it's checked
		return false, -1
	}
}

func buildCallInfo(call *ast.CallExpr, info *types.Info, fset *token.FileSet, file *ast.File, fpath string, src []byte, pkg goListPkg, errPositions []int) callInfo {
	var ci callInfo
	ci.filename = fpath
	pos := fset.Position(call.Pos())
	ci.line = pos.Line
	ci.col = pos.Column
	ci.callText = extractCallText(src, fset, call)

	// Determine function object
	// For selector like os.Chdir, Fun is SelectorExpr
	// For ident like foo(), Fun is Ident
	// Use info to get object
	var obj types.Object
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		obj = info.ObjectOf(fun)
		if obj == nil {
			// Try uses
			obj = info.Uses[fun]
		}
	case *ast.SelectorExpr:
		// For selector, the Sel ident is the function/method name
		obj = info.Uses[fun.Sel]
		if obj == nil {
			obj = info.Defs[fun.Sel]
		}
	}

	if obj != nil {
		// Check if it's a function
		if fn, ok := obj.(*types.Func); ok {
			sig, ok := fn.Type().(*types.Signature)
			if ok {
				// Check receiver
				if recv := sig.Recv(); recv != nil {
					ci.isMethod = true
					recvType := recv.Type()
					ci.receiver = recvType.String() // e.g., "*bytes.Buffer"
					// For verbose identifier, we need formatted receiver with package path
					// recvType.String() already includes package path? For bytes.Buffer, it gives "*bytes.Buffer"
					// For local types, it gives "*example.com/pkg.Type" or "example.com/pkg.Type"
					ci.methodName = fn.Name()
					// Build identifier for verbose: "(*receiver).Method" or "(receiver).Method"
					// receiver string is like "*bytes.Buffer" -> we want "(*bytes.Buffer).Method"
					// If receiver starts with "*", then identifier is "(*<type without *>).Method" ? Actually "*bytes.Buffer" should become "(*bytes.Buffer).Method"
					// Let's format:
					// If recvType is pointer, then its elem is named, string is "*bytes.Buffer" -> we want "(*bytes.Buffer).Method"
					// If recvType is value, string "bytes.Buffer" -> "(bytes.Buffer).Method"
					// For pointer, we need to handle: recvType.String() = "*bytes.Buffer" -> trim "*" and then wrap as "(*<rest>).Method"
					if strings.HasPrefix(ci.receiver, "*") {
						trimmed := strings.TrimPrefix(ci.receiver, "*")
						ci.identifier = fmt.Sprintf("(*%s).%s", trimmed, ci.methodName)
					} else {
						ci.identifier = fmt.Sprintf("(%s).%s", ci.receiver, ci.methodName)
					}
					ci.pkgPath = "" // for method, pkgPath not used for func matching, but receiver used
					ci.funcName = ci.methodName
				} else {
					// Function (no receiver)
					ci.isMethod = false
					// Get package path
					if fn.Pkg() != nil {
						ci.pkgPath = fn.Pkg().Path()
					} else {
						ci.pkgPath = pkg.ImportPath // fallback to current package?
					}
					ci.funcName = fn.Name()
					// Identifier for verbose: if same package, identifier should be omitted? But we will still build it as pkgPath + "." + funcName for different package case
					// For same package, we will have logic in main to omit
					ci.identifier = fmt.Sprintf("%s.%s", ci.pkgPath, ci.funcName)
					// For builtin functions like println, Pkg() is nil, so identifier maybe "println"?
					if ci.pkgPath == "" {
						ci.identifier = ci.funcName
					}
				}
			}
		}
	}

	// For first arg handling
	if len(call.Args) > 0 {
		firstArg := call.Args[0]
		// Check if first arg is os.Stdout or os.Stderr literal
		if sel, ok := firstArg.(*ast.SelectorExpr); ok {
			if ident, ok := sel.X.(*ast.Ident); ok {
				if ident.Name == "os" && (sel.Sel.Name == "Stdout" || sel.Sel.Name == "Stderr") {
					if sel.Sel.Name == "Stdout" {
						ci.firstArgIsOsStdout = true
					} else {
						ci.firstArgIsOsStderr = true
					}
				}
			}
		}
		// Get type of first arg
		t := info.TypeOf(firstArg)
		if t != nil {
			ci.firstArgType = t.String()
		}
	}

	return ci
}

func extractCallText(src []byte, fset *token.FileSet, call *ast.CallExpr) string {
	// Get file
	file := fset.File(call.Pos())
	if file == nil {
		return ""
	}
	start := file.Offset(call.Pos())
	end := file.Offset(call.End())
	if start < 0 || end < 0 || start >= len(src) || end > len(src) || start >= end {
		return ""
	}
	return string(src[start:end])
}

func extractTypeAssertText(src []byte, fset *token.FileSet, ta *ast.TypeAssertExpr) string {
	file := fset.File(ta.Pos())
	if file == nil {
		return ""
	}
	start := file.Offset(ta.Pos())
	end := file.Offset(ta.End())
	if start < 0 || end < 0 || start >= len(src) || end > len(src) || start >= end {
		return ""
	}
	return string(src[start:end])
}

func isExcluded(ci callInfo, excludes []excludeEntry) bool {
	for _, e := range excludes {
		if e.isMethod {
			if !ci.isMethod {
				continue
			}
			// Receiver must match
			// e.receiver is like "bytes.Buffer" or "*bytes.Buffer"
			// ci.receiver is like "*bytes.Buffer"
			if e.receiver != ci.receiver {
				// Also consider that entry might be without star but actual is with star? We require exact match as observed
				continue
			}
			if e.funcName != ci.methodName {
				continue
			}
			// Check arg filter
			if e.argFilter != "" {
				if e.argIsSpecial {
					if e.argFilter == "os.Stdout" && !ci.firstArgIsOsStdout {
						continue
					}
					if e.argFilter == "os.Stderr" && !ci.firstArgIsOsStderr {
						continue
					}
				} else {
					// Type filter
					if ci.firstArgType != e.argFilter {
						continue
					}
				}
			}
			return true
		} else {
			if ci.isMethod {
				continue
			}
			// Function
			// If entry pkgPath empty, match any package with same func name
			if e.pkgPath != "" && e.pkgPath != ci.pkgPath {
				// Also need to handle vendor paths? For simplicity, check suffix?
				// The README says when vendored, specify full import path including vendor
				// So we require exact match, but also allow if ci.pkgPath ends with "/vendor/"+e.pkgPath or contains?
				// For simplicity, exact match or suffix match
				if !strings.HasSuffix(ci.pkgPath, e.pkgPath) {
					continue
				}
			}
			if e.funcName != ci.funcName {
				continue
			}
			if e.argFilter != "" {
				if e.argIsSpecial {
					if e.argFilter == "os.Stdout" && !ci.firstArgIsOsStdout {
						continue
					}
					if e.argFilter == "os.Stderr" && !ci.firstArgIsOsStderr {
						continue
					}
				} else {
					if ci.firstArgType != e.argFilter {
						continue
					}
				}
			}
			return true
		}
	}
	return false
}

func isIgnoredByIgnorePkg(importPath string, ignorePkgs []string) bool {
	for _, ip := range ignorePkgs {
		if importPath == ip {
			return true
		}
	}
	return false
}

func isIgnoredByRules(ci callInfo, rules []ignoreRule, currentPkgPath string) bool {
	// For each rule, check if pkgPattern matches current call's pkgPath or current package?
	// Actually ignore rules are about package of the called function, not current package?
	// Doc: -ignore takes list of pairs pkg:regex, regex is used to ignore names within pkg.
	// So pkgPattern is package path of called function (where the function is defined), not caller.
	// And regex is applied to function name (or method name?)

	// For our ci, pkgPath is called function's package path (for func) or for method, we need to get package of receiver? For method, pkgPattern should match receiver's package? Let's assume same as ci.pkgPath for func, and for method, use receiver's package? Simpler: for method, use ci.receiver's package part?

	// We'll implement: For each rule, if pkgPattern == "" then regex applies to all packages, check if regex matches funcName or methodName
	// If pkgPattern != "" then check if ci.pkgPath == pkgPattern (exact) or ci.receiver contains pkgPattern? For method, we need to extract package from receiver.

	// Also need to handle that by default fmt is ignored? But we have builtin list that already includes many fmt.

	// For our implementation, we will check:

	for _, r := range rules {
		var targetPkg string
		var targetName string
		if ci.isMethod {
			// For method, targetPkg could be extracted from receiver? Receiver string like "bytes.Buffer" => package "bytes"
			// Or "*bytes.Buffer" => package "bytes"
			// For "example.com/pkg.Type" => package "example.com/pkg"
			// Let's extract package from receiver: up to last dot before type name?
			// Receiver string like "*bytes.Buffer" -> trim "*", then last dot separates pkg and type: "bytes" and "Buffer"
			// So package is "bytes"
			// For "example.com/method.S" -> package "example.com/method", type "S"
			// We'll parse
			recv := ci.receiver
			if strings.HasPrefix(recv, "*") {
				recv = strings.TrimPrefix(recv, "*")
			}
			lastDot := strings.LastIndex(recv, ".")
			if lastDot != -1 {
				targetPkg = recv[:lastDot]
			} else {
				targetPkg = ""
			}
			targetName = ci.methodName
		} else {
			targetPkg = ci.pkgPath
			targetName = ci.funcName
		}

		if r.pkgPattern != "" {
			// Check if targetPkg matches pkgPattern (exact or suffix?)
			// For simplicity, exact match
			if targetPkg != r.pkgPattern {
				continue
			}
		}
		if r.re.MatchString(targetName) {
			return true
		}
	}
	return false
}

