type excludeEntry struct {
	isMethod     bool
	receiver     string // e.g., "bytes.Buffer" or "*bytes.Buffer" or "example.com/pkg.Type"
	funcName     string
	pkgPath      string // for func
	full         string
	argFilter    string // e.g., "*bytes.Buffer" or "os.Stdout"
	argIsSpecial bool
}

func parseExcludeLine(line string) (excludeEntry, error) {
	line = strings.TrimSpace(line)
	base := line
	argFilter := ""
	if strings.HasSuffix(line, ")") {
		lastOpen := strings.LastIndex(line, "(")
		if lastOpen != -1 {
			// Ensure this is arg filter, not just receiver without method? Receiver method would not end with ")" if no filter, because method line ends with method name, not ")"
			// But for cases like "(*bytes.Buffer).Write", it ends with "Write", not ")".
			// So any line ending with ")" likely has arg filter, except maybe "(S).Foo" would end with ")"? No, "(S).Foo" ends with "Foo", not ")".
			// For safety, if base contains ")." before lastOpen, then it's likely filter, because receiver's ")" is followed by dot.
			// So we can check if there's a dot after first closing paren.
			filterContent := strings.TrimSpace(line[lastOpen+1 : len(line)-1])
			// If base before lastOpen contains ")." then this suffix is arg filter
			// Actually for "io.Copy(*bytes.Buffer)", base before lastOpen is "io.Copy" which contains dot but not ")."
			// For "(bytes.Buffer).Write(*bytes.Buffer)", base before lastOpen is "(bytes.Buffer).Write" which contains ")."
			// So we can treat any suffix at end as filter if base is not just "(...)"? Let's treat as filter if after removing suffix, remaining base is not empty and not just a receiver.
			// Simpler: treat as filter always when line ends with ")" and lastOpen > 0 and line[:lastOpen] contains "." (for func) or ")." (for method)
			if filterContent != "" {
				base = strings.TrimSpace(line[:lastOpen])
				argFilter = filterContent
			}
		}
	}
	var entry excludeEntry
	entry.full = line
	entry.argFilter = argFilter
	if argFilter == "os.Stdout" || argFilter == "os.Stderr" {
		entry.argIsSpecial = true
	}
	if strings.HasPrefix(base, "(") {
		closeIdx := strings.Index(base, ")")
		if closeIdx == -1 {
			return entry, fmt.Errorf("invalid method entry %q", line)
		}
		receiverInside := strings.TrimSpace(base[1:closeIdx])
		remaining := strings.TrimSpace(base[closeIdx+1:])
		if !strings.HasPrefix(remaining, ".") {
			return entry, fmt.Errorf("invalid method entry %q", line)
		}
		methodName := strings.TrimSpace(remaining[1:])
		// methodName may contain spaces? Should be clean
		entry.isMethod = true
		entry.receiver = receiverInside
		entry.funcName = methodName
	} else {
		lastDot := strings.LastIndex(base, ".")
		if lastDot == -1 {
			entry.isMethod = false
			entry.pkgPath = ""
			entry.funcName = base
		} else {
			entry.isMethod = false
			entry.pkgPath = strings.TrimSpace(base[:lastDot])
			entry.funcName = strings.TrimSpace(base[lastDot+1:])
		}
	}
	return entry, nil
}

func parseExcludeFile(path string) ([]excludeEntry, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	var entries []excludeEntry
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "//") {
			continue
		}
		e, err := parseExcludeLine(line)
		if err != nil {
			// skip invalid lines? Original probably skips? But we will skip
			continue
		}
		entries = append(entries, e)
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return entries, nil
}

func builtinExcludes() []excludeEntry {
	lines := []string{
		"(*bytes.Buffer).Write",
