		Err string `json:"Err"`
	} `json:"Error"`
}

func loadGoList(patterns []string, tags []string, mod string) ([]goListPkg, error) {
	args := []string{"list", "-json"}
	if len(tags) > 0 {
		args = append(args, "-tags", strings.Join(tags, ","))
	}
	if mod != "" {
		args = append(args, "-mod", mod)
	}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	var out bytes.Buffer
	var errOut bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errOut
	err := cmd.Run()
	// Even if err, we may have partial output, try to parse
	dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
	var pkgs []goListPkg
	for {
		var p goListPkg
		if err := dec.Decode(&p); err != nil {
			if err == io.EOF {
				break
			}
			break
		}
		pkgs = append(pkgs, p)
	}
	if err != nil && len(pkgs) == 0 {
		// Return error as failed to check packages
		return nil, fmt.Errorf("errors while loading packages: %s: %s", strings.Join(patterns, " "), errOut.String())
	}
	// Check for errors in packages
	for _, p := range pkgs {
		if p.Error != nil && p.Error.Err != "" {
			// Return as error
			return nil, fmt.Errorf("errors while loading package %s: [%s]", p.ImportPath, p.Error.Err)
		}
	}
	// Also need to consider go list stderr for pattern errors like "package help is not in std"
	if errOut.Len() > 0 {
		// The original binary prints error like "error: failed to check packages: errors while loading package help: [-: package help is not in std ...]"
		// The go list stderr may contain "package help is not in std ..."
		// We need to capture that and return as error
		// For simplicity, if errOut contains "package" and "is not in", treat as load error
		stderrStr := errOut.String()
		// Check if output is empty and stderr contains something - then we have load error
		if len(pkgs) == 0 && stderrStr != "" {
			// Try to extract package name from patterns?
			// The original formats: "errors while loading package <pattern>: [-: <error>]"
			// We'll construct similar
			// For pattern "help", it says "package help is not in std (/usr/local/go/src/help)"
			// So we can return error with that message
			return nil, fmt.Errorf("errors while loading package %s: [-: %s]", strings.Join(patterns, " "), strings.TrimSpace(stderrStr))
		}
		// If pkgs loaded but stderr has errors about pattern, still need to handle
		// For example, when pattern "notexist", go list prints error to stderr but also maybe no json?
		// We already handled len pkgs ==0
	}
	return pkgs, nil
}

