func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	// Check if type is exactly error (interface)
	if t.String() == "error" {
		return true
	}
	// Check if implements error interface
	// error interface is interface with method Error() string
	// We can check if type has method Error() string
	// For named types
	switch tt := t.(type) {
	case *types.Named:
		// Check methods
		// Also check if underlying is interface?
		// For named that is error itself? Already handled
		// Check if it implements error by checking method set
		// Simple: if type has method Error() string
		// Use method set of pointer?
		// We'll check both value and pointer method sets
		// Actually for error implementation, we need to see if type implements error interface
		// We can use types.Implements? But that needs error interface type
		// Let's try to get error type via universe?
		// For now, also check if named's underlying is struct with Error method?
		// We'll attempt to check method set
		// Check if there's method Error() string
		obj := tt.Obj()
		if obj != nil {
			// Look up Error method in named's method set
			// Use types.NewMethodSet
			mset := types.NewMethodSet(tt)
			for i:=0;i<mset.Len();i++{
				sel := mset.At(i)
				if sel.Obj().Name() == "Error" {
					// Check signature
					if sig, ok := sel.Type().(*types.Signature); ok {
						if sig.Results()!=nil && sig.Results().Len()==1 {
							if sig.Results().At(0).Type().String() == "string" {
								return true
							}
						}
					}
				}
			}
			// Also check pointer method set
			msetPtr := types.NewMethodSet(types.NewPointer(tt))
			for i:=0;i<msetPtr.Len();i++{
				sel := msetPtr.At(i)
				if sel.Obj().Name() == "Error" {
					if sig, ok := sel.Type().(*types.Signature); ok {
						if sig.Results()!=nil && sig.Results().Len()==1 && sig.Results().At(0).Type().String()=="string" {
							return true
						}
					}
				}
			}
		}
	case *types.Pointer:
		return isErrorType(tt.Elem())
	case *types.Interface:
		// If interface is error itself? Its string is "error"
		if tt.NumMethods()==1 {
			m := tt.Method(0)
			if m.Name()=="Error" {
				return true
			}
		}
	}
	return false
}

func typeString(t types.Type) string {
	if t == nil {
		return ""
	}
	return t.String()
