func isIgnoredByRules(ci callInfo, rules []ignoreRule, currentPkgPath string) bool {
	// For each rule, check if pkgPattern matches current call's pkgPath or current package?
	// Actually ignore rules are about package of the called function, not current package?
	// Doc: -ignore takes list of pairs pkg:regex, regex is used to ignore names within pkg.
	// So pkgPattern is package path of called function (where the function is defined), not caller.
	// And regex is applied to function name (or method name?)

	// For our ci, pkgPath is called function's package path (for func) or for method, we need to get package of receiver? For method, pkgPattern should match receiver's package? Let's assume same as ci.pkgPath for func, and for method, use receiver's package? Simpler: for method, use ci.receiver's package part?

	// We'll implement: For each rule, if pkgPattern == "" then regex applies to all packages, check if regex matches funcName or methodName
	// If pkgPattern != "" then check if ci.pkgPath == pkgPattern (exact) or ci.receiver contains pkgPattern? For method, we need to extract package from receiver.

	// Also need to handle that by default fmt is ignored? But we have builtin list that already includes many fmt.

	// For our implementation, we will check:

	for _, r := range rules {
		var targetPkg string
		var targetName string
		if ci.isMethod {
			// For method, targetPkg could be extracted from receiver? Receiver string like "bytes.Buffer" => package "bytes"
			// Or "*bytes.Buffer" => package "bytes"
			// For "example.com/pkg.Type" => package "example.com/pkg"
			// Let's extract package from receiver: up to last dot before type name?
			// Receiver string like "*bytes.Buffer" -> trim "*", then last dot separates pkg and type: "bytes" and "Buffer"
			// So package is "bytes"
			// For "example.com/method.S" -> package "example.com/method", type "S"
			// We'll parse
			recv := ci.receiver
			if strings.HasPrefix(recv, "*") {
				recv = strings.TrimPrefix(recv, "*")
			}
			lastDot := strings.LastIndex(recv, ".")
			if lastDot != -1 {
				targetPkg = recv[:lastDot]
			} else {
				targetPkg = ""
			}
			targetName = ci.methodName
		} else {
			targetPkg = ci.pkgPath
			targetName = ci.funcName
		}

		if r.pkgPattern != "" {
			// Check if targetPkg matches pkgPattern (exact or suffix?)
			// For simplicity, exact match
			if targetPkg != r.pkgPattern {
				continue
			}
		}
		if r.re.MatchString(targetName) {
			return true
		}
	}
	return false
}

