type ignoreFlag []string
func (i *ignoreFlag) String() string { return strings.Join(*i, ",") }
func (i *ignoreFlag) Set(v string) error {
	for _, p := range strings.Split(v, ",") {
		p = strings.TrimSpace(p)
		if p != "" { *i = append(*i, p) }
	}
	return nil
}
var flagIgnore ignoreFlag

type tagsFlag []string
func (t *tagsFlag) String() string { return strings.Join(*t, ",") }
func (t *tagsFlag) Set(v string) error {
	for _, p := range strings.FieldsFunc(v, func(r rune) bool { return r==',' || r==' ' || r=='\t' || r=='\n' }) {
		p = strings.TrimSpace(p)
		if p != "" { *t = append(*t, p) }
	}
	return nil
}
var flagTags tagsFlag

func init() {
	flag.Var(&flagIgnore, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	flag.Var(&flagTags, "tags", "comma or space-separated list of build tags to include")
}

type excludeEntry struct {
	isMethod     bool
	receiver     string
	funcName     string
	pkgPath      string
	full         string
	argFilter    string
	argIsSpecial bool
}

func parseExcludeLine(line string) (excludeEntry, error) {
	line = strings.TrimSpace(line)
	base := line
	argFilter := ""
	if strings.HasSuffix(line, ")") {
		lastOpen := strings.LastIndex(line, "(")
		if lastOpen != -1 {
			filterContent := strings.TrimSpace(line[lastOpen+1 : len(line)-1])
			if filterContent != "" {
				base = strings.TrimSpace(line[:lastOpen])
				argFilter = filterContent
			}
		}
	}
	var e excludeEntry
	e.full = line
	e.argFilter = argFilter
	if argFilter == "os.Stdout" || argFilter == "os.Stderr" {
		e.argIsSpecial = true
	}
	if strings.HasPrefix(base, "(") {
		closeIdx := strings.Index(base, ")")
		if closeIdx == -1 {
			return e, fmt.Errorf("invalid")
		}
		recv := strings.TrimSpace(base[1:closeIdx])
		rest := strings.TrimSpace(base[closeIdx+1:])
		if !strings.HasPrefix(rest, ".") {
			return e, fmt.Errorf("invalid")
		}
		method := strings.TrimSpace(rest[1:])
		e.isMethod = true
		e.receiver = recv
		e.funcName = method
	} else {
		lastDot := strings.LastIndex(base, ".")
		if lastDot == -1 {
			e.isMethod = false
			e.pkgPath = ""
			e.funcName = base
		} else {
			e.isMethod = false
			e.pkgPath = strings.TrimSpace(base[:lastDot])
			e.funcName = strings.TrimSpace(base[lastDot+1:])
		}
	}
	return e, nil
}

func parseExcludeFile(path string) ([]excludeEntry, error) {
	f, err := os.Open(path)
	if err != nil { return nil, err }
	defer f.Close()
	var entries []excludeEntry
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "//") { continue }
		e, err := parseExcludeLine(line)
		if err != nil { continue }
		entries = append(entries, e)
	}
	return entries, sc.Err()
}

func builtinExcludes() []excludeEntry {
	lines := []string{
		"(*bytes.Buffer).Write",
		"(*bytes.Buffer).WriteString",
		"(*bytes.Buffer).WriteByte",
		"(*bytes.Buffer).WriteRune",
		"(*strings.Builder).Write",
		"(*strings.Builder).WriteString",
		"(*strings.Builder).WriteByte",
		"(*strings.Builder).WriteRune",
		"(hash.Hash).Write",
		"(io.Writer).Write",
		"fmt.Print",
		"fmt.Println",
		"fmt.Printf",
		"fmt.Fprint(*bytes.Buffer)",
		"fmt.Fprintf(*bytes.Buffer)",
		"fmt.Fprintln(*bytes.Buffer)",
		"fmt.Fprint(*strings.Builder)",
		"fmt.Fprintf(*strings.Builder)",
		"fmt.Fprintln(*strings.Builder)",
		"fmt.Fprint(os.Stderr)",
		"fmt.Fprintf(os.Stderr)",
		"fmt.Fprintln(os.Stderr)",
	}
	var entries []excludeEntry
	for _, l := range lines {
		e, _ := parseExcludeLine(l)
		entries = append(entries, e)
	}
	return entries
}

type ignoreRule struct {
	pkgPattern string
	re *regexp.Regexp
}

func parseIgnoreRules(ign []string) ([]ignoreRule, error) {
	var rules []ignoreRule
	for _, entry := range ign {
		parts := strings.SplitN(entry, ":", 2)
		var pkgPat, reStr string
		if len(parts)==2 {
			pkgPat = strings.TrimSpace(parts[0])
			reStr = strings.TrimSpace(parts[1])
		} else {
			pkgPat = ""
			reStr = strings.TrimSpace(parts[0])
		}
		if reStr=="" { continue }
		re, err := regexp.Compile(reStr)
		if err != nil { return nil, err }
		rules = append(rules, ignoreRule{pkgPattern: pkgPat, re: re})
	}
	return rules, nil
}

type goListPkg struct {
	Dir           string   `json:"Dir"`
	ImportPath    string   `json:"ImportPath"`
	Name          string   `json:"Name"`
	GoFiles       []string `json:"GoFiles"`
	TestGoFiles   []string `json:"TestGoFiles"`
	XTestGoFiles  []string `json:"XTestGoFiles"`
	Deps          []string `json:"Deps"`
	Error *struct{
		Err string `json:"Err"`
	} `json:"Error"`
}

func loadGoList(patterns []string, tags []string, mod string) ([]goListPkg, string, error) {
	args := []string{"list", "-json"}
	if len(tags)>0 {
		args = append(args, "-tags", strings.Join(tags, ","))
	}
	if mod != "" {
		args = append(args, "-mod", mod)
	}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	var out bytes.Buffer
	var errOut bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errOut
	err := cmd.Run()
	dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
	var pkgs []goListPkg
	for {
		var p goListPkg
		if err := dec.Decode(&p); err != nil {
			if err==io.EOF { break }
			break
		}
		pkgs = append(pkgs, p)
	}
	stderrStr := errOut.String()
	if err != nil && len(pkgs)==0 {
		return nil, stderrStr, fmt.Errorf("errors while loading package %s: [-: %s]", strings.Join(patterns, " "), strings.TrimSpace(stderrStr))
	}
	for _, p := range pkgs {
		if p.Error != nil && p.Error.Err != "" {
			return nil, stderrStr, fmt.Errorf("errors while loading package %s: [%s]", p.ImportPath, p.Error.Err)
		}
	}
	if len(pkgs)==0 && stderrStr != "" {
		return nil, stderrStr, fmt.Errorf("errors while loading package %s: [-: %s]", strings.Join(patterns, " "), strings.TrimSpace(stderrStr))
	}
	return pkgs, stderrStr, nil
}

func isErrorType(t types.Type) bool {
	if t==nil { return false }
	if t.String()=="error" { return true }
	switch tt := t.(type) {
	case *types.Named:
		mset := types.NewMethodSet(tt)
		for i:=0;i<mset.Len();i++{
			sel := mset.At(i)
			if sel.Obj().Name()=="Error" {
				if sig, ok := sel.Type().(*types.Signature); ok {
					if sig.Results()!=nil && sig.Results().Len()==1 && sig.Results().At(0).Type().String()=="string" {
						return true
					}
				}
			}
		}
		msetPtr := types.NewMethodSet(types.NewPointer(tt))
		for i:=0;i<msetPtr.Len();i++{
			sel := msetPtr.At(i)
			if sel.Obj().Name()=="Error" {
				if sig, ok := sel.Type().(*types.Signature); ok {
					if sig.Results()!=nil && sig.Results().Len()==1 && sig.Results().At(0).Type().String()=="string" {
						return true
					}
				}
			}
		}
	case *types.Pointer:
		return isErrorType(tt.Elem())
	case *types.Interface:
		if tt.NumMethods()==1 {
			m := tt.Method(0)
			if m.Name()=="Error" { return true }
		}
	}
	return false
}

func isGenerated(src []byte) bool {
	s := string(src)
	return strings.Contains(s, "Code generated") && strings.Contains(s, "DO NOT EDIT")
}

func getLineContent(src []byte, lineNum int) string {
	lines := strings.Split(string(src), "\n")
	if lineNum-1 < 0 || lineNum-1 >= len(lines) {
		return ""
	}
	return strings.TrimSpace(lines[lineNum-1])
}

type callInfo struct {
	isMethod bool
	receiver string
	methodName string
	pkgPath string
	funcName string
	firstArgType string
	firstArgIsStdout bool
	firstArgIsStderr bool
	identifier string
}

func buildCallInfo(call *ast.CallExpr, info *types.Info) callInfo {
	var ci callInfo
	var obj types.Object
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		obj = info.Uses[fun]
		if obj==nil { obj = info.Defs[fun] }
	case *ast.SelectorExpr:
		obj = info.Uses[fun.Sel]
		if obj==nil { obj = info.Defs[fun.Sel] }
	}
	if obj!=nil {
		if fn, ok := obj.(*types.Func); ok {
			if sig, ok := fn.Type().(*types.Signature); ok {
				if recv := sig.Recv(); recv!=nil {
					ci.isMethod = true
					recvType := recv.Type()
					ci.receiver = recvType.String()
					ci.methodName = fn.Name()
					ci.funcName = fn.Name()
					if strings.HasPrefix(ci.receiver, "*") {
						trim := strings.TrimPrefix(ci.receiver, "*")
						ci.identifier = fmt.Sprintf("(*%s).%s", trim, ci.methodName)
					} else {
						ci.identifier = fmt.Sprintf("(%s).%s", ci.receiver, ci.methodName)
					}
				} else {
					ci.isMethod = false
					if fn.Pkg()!=nil {
						ci.pkgPath = fn.Pkg().Path()
					}
					ci.funcName = fn.Name()
					ci.identifier = fmt.Sprintf("%s.%s", ci.pkgPath, ci.funcName)
					if ci.pkgPath=="" {
						ci.identifier = ci.funcName
					}
				}
			}
		}
	}
	if len(call.Args)>0 {
		first := call.Args[0]
		if sel, ok := first.(*ast.SelectorExpr); ok {
			if ident, ok := sel.X.(*ast.Ident); ok && ident.Name=="os" {
				if sel.Sel.Name=="Stdout" { ci.firstArgIsStdout=true }
				if sel.Sel.Name=="Stderr" { ci.firstArgIsStderr=true }
			}
		}
		if t := info.TypeOf(first); t!=nil {
			ci.firstArgType = t.String()
		}
	}
	return ci
}

func isExcluded(ci callInfo, excludes []excludeEntry) bool {
	for _, e := range excludes {
		if e.isMethod {
			if !ci.isMethod { continue }
			if e.receiver != ci.receiver { continue }
			if e.funcName != ci.methodName { continue }
			if e.argFilter != "" {
				if e.argIsSpecial {
					if e.argFilter=="os.Stdout" && !ci.firstArgIsStdout { continue }
					if e.argFilter=="os.Stderr" && !ci.firstArgIsStderr { continue }
				} else {
					if ci.firstArgType != e.argFilter { continue }
				}
			}
			return true
		} else {
			if ci.isMethod { continue }
			if e.pkgPath != "" && e.pkgPath != ci.pkgPath {
				if !strings.HasSuffix(ci.pkgPath, e.pkgPath) { continue }
			}
			if e.funcName != ci.funcName { continue }
			if e.argFilter != "" {
				if e.argIsSpecial {
					if e.argFilter=="os.Stdout" && !ci.firstArgIsStdout { continue }
					if e.argFilter=="os.Stderr" && !ci.firstArgIsStderr { continue }
				} else {
					if ci.firstArgType != e.argFilter { continue }
				}
			}
			return true
		}
	}
	return false
}

func isIgnoredByPkgPath(importPath string, ignorePkgs []string) bool {
	for _, ip := range ignorePkgs {
		if importPath == ip { return true }
	}
	return false
}

func isIgnoredByRules(ci callInfo, rules []ignoreRule) bool {
	for _, r := range rules {
		var targetPkg, targetName string
		if ci.isMethod {
			recv := ci.receiver
			if strings.HasPrefix(recv, "*") { recv = strings.TrimPrefix(recv, "*") }
			lastDot := strings.LastIndex(recv, ".")
			if lastDot != -1 {
				targetPkg = recv[:lastDot]
			}
			targetName = ci.methodName
		} else {
			targetPkg = ci.pkgPath
			targetName = ci.funcName
		}
		if r.pkgPattern != "" && r.pkgPattern != targetPkg {
			continue
		}
		if r.re.MatchString(targetName) {
			return true
		}
	}
	return false
}

func isUnchecked(parent ast.Node, call *ast.CallExpr, errPositions []int, blankFlag bool) bool {
	switch p := parent.(type) {
	case *ast.ExprStmt:
		return true
	case *ast.DeferStmt:
		return true
	case *ast.GoStmt:
		return true
	case *ast.AssignStmt:
		if len(p.Rhs)==1 {
			for _, ep := range errPositions {
				if ep < len(p.Lhs) {
					lhs := p.Lhs[ep]
					if ident, ok := lhs.(*ast.Ident); ok && ident.Name == "_" {
						if blankFlag {
							return true
						}
						continue
					}
					continue
				} else {
					return true
				}
			}
			return false
		} else {
			for rhsIdx, rhs := range p.Rhs {
				if rhs == call {
					if rhsIdx < len(p.Lhs) {
						lhs := p.Lhs[rhsIdx]
						if ident, ok := lhs.(*ast.Ident); ok && ident.Name == "_" {
							if blankFlag {
								return true
							}
							return false
						}
						return false
					} else {
						return true
					}
				}
			}
			return false
		}
	default:
		return false
	}
}

func main() {
	flag.Parse()
	patterns := flag.Args()
	if len(patterns)==0 {
		patterns = []string{"."}
	}

	var excludes []excludeEntry
	if *flagExclude != "" {
		entries, err := parseExcludeFile(*flagExclude)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
			os.Exit(2)
		}
		excludes = append(excludes, entries...)
	}
	if !*flagExcludeOnly {
		excludes = append(excludes, builtinExcludes()...)
	}

	ignoreRules, err := parseIgnoreRules(flagIgnore)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}
	var ignorePkgs []string
	if *flagIgnorePkg != "" {
		for _, p := range strings.Split(*flagIgnorePkg, ",") {
			p = strings.TrimSpace(p)
			if p != "" { ignorePkgs = append(ignorePkgs, p) }
		}
	}

	pkgs, _, err := loadGoList(patterns, flagTags, *flagMod)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}

	cwd, _ := os.Getwd()
	hasErrors := false

	for _, pkg := range pkgs {
		if isIgnoredByPkgPath(pkg.ImportPath, ignorePkgs) {
			continue
		}
		skipPkg := false
		for _, r := range ignoreRules {
			if r.pkgPattern == pkg.ImportPath && r.re.String() == ".*" {
				skipPkg = true
				break
			}
		}
		if skipPkg { continue }

		if *flagVerbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", pkg.ImportPath)
		}

		fset := token.NewFileSet()
		var files []*ast.File
		var filePaths []string
		var srcs [][]byte

		allGoFiles := pkg.GoFiles
		if !*flagIgnoreTests {
			allGoFiles = append(allGoFiles, pkg.TestGoFiles...)
			allGoFiles = append(allGoFiles, pkg.XTestGoFiles...)
		}

		for _, fname := range allGoFiles {
			if *flagIgnoreTests && strings.HasSuffix(fname, "_test.go") {
				continue
			}
			fpath := filepath.Join(pkg.Dir, fname)
			src, err := os.ReadFile(fpath)
			if err != nil { continue }
			if *flagIgnoreGenerated && isGenerated(src) {
				continue
			}
			f, err := parser.ParseFile(fset, fpath, src, parser.AllErrors|parser.ParseComments)
			if err != nil {
				if f == nil { continue }
			}
			files = append(files, f)
			filePaths = append(filePaths, fpath)
			srcs = append(srcs, src)
		}
		if len(files)==0 { continue }

		conf := types.Config{
			Importer: importer.ForCompiler(fset, "gc", nil),
		}
		info := &types.Info{
			Types: make(map[ast.Expr]types.TypeAndValue),
			Defs:  make(map[*ast.Ident]types.Object),
			Uses:  make(map[*ast.Ident]types.Object),
		}
		_, typeErr := conf.Check(pkg.ImportPath, fset, files, info)
		if typeErr != nil {
			fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s: [-: # %s\n%s]\n", pkg.ImportPath, pkg.ImportPath, typeErr)
			os.Exit(2)
		}

		for idx, file := range files {
			fpath := filePaths[idx]
			src := srcs[idx]
			var stack []ast.Node
			ast.Inspect(file, func(n ast.Node) bool {
				if n==nil {
					if len(stack)>0 { stack = stack[:len(stack)-1] }
					return true
				}
				stack = append(stack, n)

				var call *ast.CallExpr
				var typeAssertNode *ast.TypeAssertExpr
				var isTypeAssert bool

				switch node := n.(type) {
				case *ast.CallExpr:
					call = node
				case *ast.TypeAssertExpr:
					if *flagAsserts {
						isTypeAssert = true
						typeAssertNode = node
					}
				}

				if call != nil {
					t := info.TypeOf(call)
					if t==nil { return true }
					var errPos []int
					if tup, ok := t.(*types.Tuple); ok {
						for i:=0;i<tup.Len();i++{
							if isErrorType(tup.At(i).Type()) {
								errPos = append(errPos, i)
							}
						}
					} else {
						if isErrorType(t) {
							errPos = append(errPos, 0)
						}
					}
					if len(errPos)==0 { return true }

					if len(stack)<2 { return true }
					parent := stack[len(stack)-2]
					if !isUnchecked(parent, call, errPos, *flagBlank) {
						return true
					}

					ci := buildCallInfo(call, info)
					if isExcluded(ci, excludes) {
						return true
					}
					if ci.pkgPath != "" && isIgnoredByPkgPath(ci.pkgPath, ignorePkgs) {
						return true
					}
					if ci.isMethod {
						recvPkg := ""
						recv := ci.receiver
						if strings.HasPrefix(recv, "*") { recv = strings.TrimPrefix(recv, "*") }
						if lastDot := strings.LastIndex(recv, "."); lastDot!=-1 {
							recvPkg = recv[:lastDot]
						}
						if recvPkg != "" && isIgnoredByPkgPath(recvPkg, ignorePkgs) {
							return true
						}
					}
					if isIgnoredByRules(ci, ignoreRules) {
						return true
					}

					hasErrors = true
					printFile := fpath
					if !*flagAbspath {
						if rel, err := filepath.Rel(cwd, fpath); err==nil {
							printFile = rel
						}
					}
					pos := fset.Position(call.Pos())
					lineContent := getLineContent(src, pos.Line)
					if *flagVerbose {
						if !ci.isMethod && ci.pkgPath == pkg.ImportPath {
							fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, lineContent)
						} else {
							if ci.identifier != "" {
								fmt.Printf("%s:%d:%d:\t%s\t%s\n", printFile, pos.Line, pos.Column, ci.identifier, lineContent)
							} else {
								fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, lineContent)
							}
						}
					} else {
						fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, lineContent)
					}
				} else if isTypeAssert {
					if len(stack)<2 { return true }
					parent := stack[len(stack)-2]
					unchecked := false
					switch p := parent.(type) {
					case *ast.ExprStmt:
						unchecked = true
					case *ast.DeferStmt, *ast.GoStmt:
						unchecked = true
					case *ast.AssignStmt:
						if len(p.Rhs)==1 && len(p.Lhs)==1 {
							if p.Rhs[0]==typeAssertNode {
								if ident, ok := p.Lhs[0].(*ast.Ident); ok && ident.Name=="_" {
									if *flagBlank { unchecked=true }
								}
							}
						} else if len(p.Rhs)==1 && len(p.Lhs)==2 {
							if p.Rhs[0]==typeAssertNode {
								if ident, ok := p.Lhs[0].(*ast.Ident); ok && ident.Name=="_" {
									if *flagBlank { unchecked=true }
								}
							}
						} else {
							for rhsIdx, rhs := range p.Rhs {
								if rhs==typeAssertNode {
									if rhsIdx < len(p.Lhs) {
										if ident, ok := p.Lhs[rhsIdx].(*ast.Ident); ok && ident.Name=="_" {
											if *flagBlank { unchecked=true }
										}
									} else {
										unchecked=true
									}
								}
							}
						}
					}
					if unchecked {
						hasErrors = true
						printFile := fpath
						if !*flagAbspath {
							if rel, err := filepath.Rel(cwd, fpath); err==nil { printFile = rel }
						}
						pos := fset.Position(typeAssertNode.Pos())
						lineContent := getLineContent(src, pos.Line)
						fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, lineContent)
					}
				}

				return true
			})
		}
	}

	if hasErrors {
		os.Exit(1)
	}
	os.Exit(0)
}
EOF
cd /workspace && go run . --help 2>&1 | head -n 20
"}

