func getLineContent(src []byte, lineNum int) string {
	lines := strings.Split(string(src), "\n")
	if lineNum-1 < 0 || lineNum-1 >= len(lines) {
		return ""
	}
	return strings.TrimSpace(lines[lineNum-1])
}

type callInfo struct {
	isMethod bool
	receiver string
	methodName string
	pkgPath string
	funcName string
	firstArgType string
	firstArgIsStdout bool
	firstArgIsStderr bool
	identifier string
}

func buildCallInfo(call *ast.CallExpr, info *types.Info) callInfo {
	var ci callInfo
	var obj types.Object
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		obj = info.Uses[fun]
		if obj==nil { obj = info.Defs[fun] }
	case *ast.SelectorExpr:
		obj = info.Uses[fun.Sel]
		if obj==nil { obj = info.Defs[fun.Sel] }
	}
	if obj!=nil {
		if fn, ok := obj.(*types.Func); ok {
			if sig, ok := fn.Type().(*types.Signature); ok {
				if recv := sig.Recv(); recv!=nil {
					ci.isMethod = true
					recvType := recv.Type()
					ci.receiver = recvType.String()
					ci.methodName = fn.Name()
					ci.funcName = fn.Name()
					if strings.HasPrefix(ci.receiver, "*") {
						trim := strings.TrimPrefix(ci.receiver, "*")
						ci.identifier = fmt.Sprintf("(*%s).%s", trim, ci.methodName)
					} else {
						ci.identifier = fmt.Sprintf("(%s).%s", ci.receiver, ci.methodName)
					}
				} else {
					ci.isMethod = false
					if fn.Pkg()!=nil {
						ci.pkgPath = fn.Pkg().Path()
					}
					ci.funcName = fn.Name()
					ci.identifier = fmt.Sprintf("%s.%s", ci.pkgPath, ci.funcName)
					if ci.pkgPath=="" {
						ci.identifier = ci.funcName
					}
				}
			}
		}
	}
	if len(call.Args)>0 {
		first := call.Args[0]
		if sel, ok := first.(*ast.SelectorExpr); ok {
			if ident, ok := sel.X.(*ast.Ident); ok && ident.Name=="os" {
				if sel.Sel.Name=="Stdout" { ci.firstArgIsStdout=true }
				if sel.Sel.Name=="Stderr" { ci.firstArgIsStderr=true }
			}
		}
		if t := info.TypeOf(first); t!=nil {
			ci.firstArgType = t.String()
		}
	}
	return ci
}

func isExcluded(ci callInfo, excludes []excludeEntry) bool {
	for _, e := range excludes {
		if e.isMethod {
			if !ci.isMethod { continue }
			if e.receiver != ci.receiver { continue }
			if e.funcName != ci.methodName { continue }
			if e.argFilter != "" {
				if e.argIsSpecial {
					if e.argFilter=="os.Stdout" && !ci.firstArgIsStdout { continue }
					if e.argFilter=="os.Stderr" && !ci.firstArgIsStderr { continue }
				} else {
					if ci.firstArgType != e.argFilter { continue }
				}
			}
			return true
		} else {
			if ci.isMethod { continue }
			if e.pkgPath != "" && e.pkgPath != ci.pkgPath {
				if !strings.HasSuffix(ci.pkgPath, e.pkgPath) { continue }
			}
			if e.funcName != ci.funcName { continue }
			if e.argFilter != "" {
				if e.argIsSpecial {
					if e.argFilter=="os.Stdout" && !ci.firstArgIsStdout { continue }
					if e.argFilter=="os.Stderr" && !ci.firstArgIsStderr { continue }
				} else {
					if ci.firstArgType != e.argFilter { continue }
				}
			}
			return true
		}
	}
	return false
}

func isIgnoredByPkgPath(importPath string, ignorePkgs []string) bool {
	for _, ip := range ignorePkgs {
		if importPath == ip { return true }
	}
	return false
}

func isIgnoredByRules(ci callInfo, rules []ignoreRule) bool {
	for _, r := range rules {
		var targetPkg, targetName string
		if ci.isMethod {
			recv := ci.receiver
			if strings.HasPrefix(recv, "*") { recv = strings.TrimPrefix(recv, "*") }
			lastDot := strings.LastIndex(recv, ".")
			if lastDot != -1 {
				targetPkg = recv[:lastDot]
			}
			targetName = ci.methodName
		} else {
			targetPkg = ci.pkgPath
			targetName = ci.funcName
		}
		if r.pkgPattern != "" && r.pkgPattern != targetPkg {
			continue
		}
		if r.re.MatchString(targetName) {
			return true
		}
	}
	return false
}

func isUnchecked(parent ast.Node, call *ast.CallExpr, errPositions []int, blankFlag bool) (bool, token.Pos) {
	switch p := parent.(type) {
	case *ast.ExprStmt:
		return true, call.Lparen
	case *ast.DeferStmt:
		return true, call.Lparen
	case *ast.GoStmt:
		return true, call.Lparen
	case *ast.AssignStmt:
		if len(p.Rhs)==1 {
			for _, ep := range errPositions {
				if ep < len(p.Lhs) {
					lhs := p.Lhs[ep]
					if ident, ok := lhs.(*ast.Ident); ok && ident.Name == "_" {
						if blankFlag {
							return true, ident.Pos()
						}
						continue
					}
					continue
				} else {
					return true, call.Lparen
				}
			}
			return false, token.NoPos
		} else {
			for rhsIdx, rhs := range p.Rhs {
				if rhs == call {
					if rhsIdx < len(p.Lhs) {
						lhs := p.Lhs[rhsIdx]
						if ident, ok := lhs.(*ast.Ident); ok && ident.Name == "_" {
							if blankFlag {
								return true, ident.Pos()
							}
							return false, token.NoPos
						}
						return false, token.NoPos
					} else {
						return true, call.Lparen
					}
				}
			}
			return false, token.NoPos
		}
	default:
		return false, token.NoPos
	}
}

func main() {
	flag.Parse()
	patterns := flag.Args()
	if len(patterns)==0 {
		patterns = []string{"."}
	}

