						}
					}
					if len(errPos) == 0 {
						return true
					}

					if len(stack) < 2 {
						return true
					}
					parent := stack[len(stack)-2]
					unchecked, reportPos := isUnchecked(parent, call, errPos, *flagBlank)
					if !unchecked {
						return true
					}

					ci := buildCallInfo(call, info)
					if isExcluded(ci, excludes) {
						return true
					}
					if ci.pkgPath != "" && isIgnoredByPkgPath(ci.pkgPath, ignorePkgs) {
						return true
					}
					if ci.isMethod {
						recvPkg := ""
						recv := ci.receiver
						if strings.HasPrefix(recv, "*") {
							recv = strings.TrimPrefix(recv, "*")
						}
						if lastDot := strings.LastIndex(recv, "."); lastDot != -1 {
							recvPkg = recv[:lastDot]
						}
						if recvPkg != "" && isIgnoredByPkgPath(recvPkg, ignorePkgs) {
							return true
						}
					}
					if isIgnoredByRules(ci, ignoreRules) {
						return true
					}

					hasErrors = true
					printFile := fpath
					if !*flagAbspath {
						if rel, err := filepath.Rel(cwd, fpath); err == nil {
							printFile = rel
						}
					}
					if reportPos == token.NoPos {
						reportPos = call.Lparen
					}
					pos := fset.Position(reportPos)
					lineContent := getLineContent(src, pos.Line)
					if *flagVerbose {
						if !ci.isMethod && ci.pkgPath == pkg.ImportPath {
							fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, lineContent)
						} else {
							if ci.identifier != "" {
								fmt.Printf("%s:%d:%d:\t%s\t%s\n", printFile, pos.Line, pos.Column, ci.identifier, lineContent)
							} else {
								fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, lineContent)
							}
						}
					} else {
						fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, lineContent)
					}
				} else if isTypeAssert {
					if len(stack) < 2 {
						return true
					}
					parent := stack[len(stack)-2]
					unchecked := false
					var reportPos token.Pos
					switch p := parent.(type) {
					case *ast.ExprStmt:
						unchecked = true
						reportPos = typeAssertNode.Pos()
					case *ast.DeferStmt, *ast.GoStmt:
						unchecked = true
						reportPos = typeAssertNode.Pos()
					case *ast.AssignStmt:
						if len(p.Rhs) == 1 && len(p.Lhs) == 1 {
							// single-value always unchecked
							if p.Rhs[0] == typeAssertNode {
								unchecked = true
								reportPos = typeAssertNode.Pos()
							}
						} else if len(p.Rhs) == 1 && len(p.Lhs) == 2 {
							// comma-ok: check if ok is blank with blank flag
							if p.Rhs[0] == typeAssertNode {
								if len(p.Lhs) >= 2 {
									if ident, ok := p.Lhs[1].(*ast.Ident); ok && ident.Name == "_" {
										if *flagBlank {
											unchecked = true
											reportPos = ident.Pos()
										}
									}
								}
							}
						} else {
							// multi RHS - treat single-value as unchecked
							for rhsIdx, rhs := range p.Rhs {
								if rhs == typeAssertNode {
									if len(p.Lhs) == 1 {
										unchecked = true
										reportPos = typeAssertNode.Pos()
									} else if rhsIdx < len(p.Lhs) {
										// For multi, if LHS is variable, single-value still unchecked?
										// For comma-ok with 2 LHS and 1 RHS already handled
										// For multi RHS, each type assert is single-value -> unchecked
										unchecked = true
										reportPos = typeAssertNode.Pos()
									}
								}
							}
						}
					default:
						// Any other use (return, arg, etc) is considered unchecked for single-value type assert
						// Check if parent is not comma-ok assign
						if _, ok := parent.(*ast.AssignStmt); !ok {
							unchecked = true
							reportPos = typeAssertNode.Pos()
						} else {
							// If parent is assign but not comma-ok (len LHS 1), already handled as always unchecked
							// For other assigns with 2 LHS, we already handled blank ok case
							// For assign with 1 LHS that is not blank? That's single-value case already flagged
							// So for default we treat as unchecked if it's single-value
							// We can check if parent assign has 1 LHS, it's single-value -> unchecked
							if assign, ok := parent.(*ast.AssignStmt); ok {
								if len(assign.Lhs) == 1 && len(assign.Rhs) == 1 && assign.Rhs[0] == typeAssertNode {
									unchecked = true
									reportPos = typeAssertNode.Pos()
								}
							}
						}
					}
					if unchecked {
						hasErrors = true
						printFile := fpath
						if !*flagAbspath {
							if rel, err := filepath.Rel(cwd, fpath); err == nil {
								printFile = rel
							}
						}
						if reportPos == token.NoPos {
							reportPos = typeAssertNode.Pos()
						}
						pos := fset.Position(reportPos)
						lineContent := getLineContent(src, pos.Line)
						fmt.Printf("%s:%d:%d:\t%s\n", printFile, pos.Line, pos.Column, lineContent)
					}
				}

				return true
			})
		}
	}

	if hasErrors {
		os.Exit(1)
	}
	os.Exit(0)
}
