var (
	flagAbspath         = flag.Bool("abspath", false, "print absolute paths to files")
	flagAsserts         = flag.Bool("asserts", false, "if true, check for ignored type assertion results")
	flagBlank           = flag.Bool("blank", false, "if true, check for errors assigned to blank identifier")
	flagExclude         = flag.String("exclude", "", "Path to a file containing a list of functions to exclude from checking")
	flagExcludeOnly     = flag.Bool("excludeonly", false, "Use only excludes from -exclude file")
